import { configureStore } from "@reduxjs/toolkit";
import { reduxStore } from "..";
import { AudioFormat, DOWNLOAD_STATE, DownloadTriggeredPayload, SetMetadataActionType, THEMES, videoAttributes, VideoFormat, VideoMetaData } from "../../interfaces";
import { REDUX_ACTIONS, VIDEO_PROVIDER } from "../../constants";

class VideoDownloaderStoreService {
  private store: ReturnType<typeof configureStore> | null;
  constructor() {
    this.store = null;
  }

  /**
   * Initializes the store by asynchronously retrieving the Redux store instance.
   * This method sets the `store` property with the obtained store.
   * 
   * @returns {Promise<void>} A promise that resolves once the store is initialized.
   */
  async initializeStore(): Promise<void> {
    this.store = await reduxStore.getStore();
  }

  /**
   * Sets the metadata in the Redux store.
   * 
   * This method initializes the store if it hasn't been initialized yet,
   * and then dispatches an action to update the metadata in the store.
   * 
   * @param payload - The metadata to be set in the store. It should conform to the `SetMetadataActionType`.
   * @returns A promise that resolves once the store initialization and dispatch are complete.
   */
  async setMetadata(payload: SetMetadataActionType) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.SET_METADATA,
      payload
   });
  }

  async setProgress(payload: {videoId: string, progressPercentage: number}) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.SET_PROGRESS,
      payload
   });
  }

  /**
   * Triggers the download process by dispatching a Redux action with the provided payload.
   * 
   * @param payload - An object containing the format of the media to be downloaded.
   *                  It can be either an `AudioFormat` or a `VideoFormat`.
   * 
   * @returns A promise that resolves once the store has been initialized and the action is dispatched.
   */
  async triggerDownload(payload: { format: DownloadTriggeredPayload, downloadSource?: string }) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.VIDEO_DOWNLOAD_STARTED,
      payload
    });
  }

  /**
   * Returns the total count of metadata entries across all providers.
   * @returns {Promise<number>} The count of metadata entries.
   */
  async getMetadataCount(): Promise<number> {
    await this.initializeStore();
    const state = this.store.getState() as any;
    const metadataValues = state.metaData?.metadataValues || {};
    let count = 0;
    for (const provider of Object.values(metadataValues)) {
      count += Object.keys(provider).length;
    }
    return count;
  }

  /**
   * Retrieves metadata for a specific video ID from a specific provider.
   * 
   * @param videoId - The unique identifier of the video.
   * @param providerName - The name of the video provider (e.g., 'youtube', 'vimeo').
   * @returns A promise that resolves to the video metadata if found, or null if not found.
   */
  async getMetadataForVideoId(videoId: string, providerName:string): Promise<VideoMetaData | null> {
    await this.initializeStore();
    const state = this.store.getState() as any;
    const metadataValues = state.metaData?.metadataValues || {};
    
    // Check if the provider exists in metadata
    if (!metadataValues[providerName]) {
      return null;
    }
    
    // Return the metadata for the specific video ID and provider
    return metadataValues[providerName][videoId] || null;
  }
  /**
   * Gets the current state of the Redux store.
   * @returns {Promise<any>} The current state of the store.
   */
  async getState(): Promise<any> {
    await this.initializeStore();
    return this.store.getState();
  }

  /**
   * Updates the download state of a video in the store.
   *
   * @param payload - An object containing the video ID and the new download state.
   * @param payload.videoId - The unique identifier of the video.
   * @param payload.downloadState - The new download state of the video, represented as a value of the `DOWNLOAD_STATE` enum.
   * @returns A promise that resolves once the store has been initialized and the state has been updated.
   */
  async setDownloadState(payload: {videoId: string, downloadState: DOWNLOAD_STATE, videoAttributes: videoAttributes}) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.UPDATE_DOWNLOAD_STATE,
      payload
    });
  }

  /**
   * Updates the application's theme by dispatching a theme change action to the Redux store.
   * 
   * @param payload - An object containing the updated theme.
   * @param payload.updatedTheme - The new theme to be applied, represented by the `THEMES` enum.
   * 
   * @returns A promise that resolves once the store has been initialized and the action has been dispatched.
   */
  async setTheme(payload: {updatedTheme: THEMES}) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.THEME_CHANGED,
      payload
    })
  }

  /**
   * Marks the End User License Agreement (EULA) as accepted by dispatching
   * the corresponding action to the Redux store. Ensures the store is
   * initialized before performing the dispatch.
   *
   * @async
   * @returns {Promise<void>} A promise that resolves once the store is initialized
   * and the action is dispatched.
   */
  async setEulaAccepted() {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.EULA_ACCEPTED,
    });
  }

  /**
   * Marks the EULA (End-User License Agreement) as dismissed in the store.
   * This method initializes the store if it hasn't been initialized yet,
   * and then dispatches an action to update the store state indicating
   * that the EULA has been dismissed.
   *
   * @async
   * @returns {Promise<void>} A promise that resolves once the action is dispatched.
   */
  async setEulaDismissed() {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.EULA_DISMISSED,
    });
  }

  async retryClicked(payload: {videoId: string, videoAttributes: videoAttributes, videoProvider: VIDEO_PROVIDER}) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.RETRY_CLICKED,
      payload
    });
  }

  async cancelClicked(payload: {videoId: string, downloadState: DOWNLOAD_STATE, videoAttributes: videoAttributes}) {
    await this.initializeStore();
    this.store.dispatch({
      type: REDUX_ACTIONS.UPDATE_DOWNLOAD_STATE,
      payload
    });
  }
}

const videoDownloaderStoreService = new VideoDownloaderStoreService();
export { videoDownloaderStoreService };