import { AudioFormat, AudioFormatMetadata, SUPPORTED_AUDIO_FORMAT, SUPPORTED_VIDEO_FORMAT, SupportedFormat, VideoFormat, VideoFormatMetadata } from "./interfaces";
import { BYTE_TO_GB_CONVERSION, BYTE_TO_MB_CONVERSION, BYTE_TO_KB_CONVERSION, MEDIA_SIZE } from "./constants";

class MediaFormatFilter {
    private mediaFilterProvidersMap: { [key: string]: Function }
    
    // Map for converting content length units to bytes for comparison
    private static readonly UNIT_CONVERSION_MAP = {
        [MEDIA_SIZE.KB]: BYTE_TO_KB_CONVERSION,
        [MEDIA_SIZE.MB]: BYTE_TO_MB_CONVERSION,
        [MEDIA_SIZE.GB]: BYTE_TO_GB_CONVERSION
    } as const;

    /**
     * Converts content length from display units back to bytes for comparison
     */
    protected convertToBytes(contentLength: number, unit: string): number {
        return contentLength * (MediaFormatFilter.UNIT_CONVERSION_MAP[unit] || BYTE_TO_MB_CONVERSION);
    }
    /**
     * Filters the provided data based on the specified supported formats.
     * @param data - The data object to be filtered, containing properties such as `mime_type` and `codecs`.
     * @param supportedFormats - An array of supported formats, where each format specifies a `mimeType` and a list of `codecs`.
     * @returns A boolean indicating whether the data matches any of the supported formats.
     */
    filterData(data: any, supportedFormats: any): any[] {
        return [];
    }

    /**
     * Formats the provided audio data into an array of `AudioFormat` objects.
     *
     * @param data - An array of raw audio data to be formatted.
     * @returns An array of `AudioFormat` objects. Currently, this method returns an empty array.
     */
    formatAudioData(data: any[]): AudioFormatMetadata[] {
        return [];
    }

    /**
     * Sorts an array of objects in descending order based on the `height` property.
     *
     * @param data - An array of objects to be sorted. Each object is expected to have a `height` property.
     * @returns The sorted array, with objects ordered from highest to lowest `height`.
     */
    private sortData(data: any) {
        return data.sort((firstValue: any, secondValue: any) => secondValue.height - firstValue.height);
    }

    /**
     * Filters and formats video data into an array of `VideoFormat` objects.
     *
     * @param data - An array of raw video data objects to be processed.
     * @returns An array of `VideoFormat` objects representing the formatted video data.
     */
    formatVideoData(data: any[]): VideoFormatMetadata[] {
        return [];
    }

    /**
     * Filters and formats audio data based on supported audio formats.
     *
     * @param data - An array of audio data objects to be filtered.
     * @param supportedAudioformats - An array of supported audio formats to filter the data against.
     * @returns An array of formatted audio data objects that match the supported formats.
     */
    getFilteredAudioData(data: any[], supportedAudioformats: SUPPORTED_AUDIO_FORMAT[]): AudioFormatMetadata[] {
        let filteredData: any = data.filter(item => 
            this.filterData(item, supportedAudioformats)
        );
        filteredData = this.sortData(filteredData);
        const formattedData: AudioFormatMetadata[] = this.formatAudioData(filteredData);
        return formattedData;
    } 

    /**
     * Filters and formats video data based on supported video formats.
     *
     * @param data - An array of video data objects to be filtered.
     * @param supportedVideoFormats - An array of supported video formats to filter the data against.
     * @returns An array of formatted video data objects that match the supported formats.
     */
    getFilteredVideoData(data: any[], supportedVideoFormats: SUPPORTED_VIDEO_FORMAT[]): VideoFormatMetadata[] {
        let filteredData: any = data.filter(item => 
            this.filterData(item, supportedVideoFormats)
        );
        // Remove HDR formats (e.g., '2160p60 HDR', or any label containing 'HDR')
        filteredData = filteredData.filter(item => {
            // If qualityLabel exists and contains 'HDR', filter it out
            if (typeof item.qualityLabel === 'string' && item.qualityLabel.toUpperCase().includes('HDR')) {
                return false;
            }
            return true;
        });
        filteredData = this.sortData(filteredData);
        const formattedData: VideoFormatMetadata[] = this.formatVideoData(filteredData);
        return formattedData;
    }

    /**
     * Returns the content length and its unit (KB, MB or GB) as a number and string.
     */
    getContentLengthInClosestUnits(contentLengthInBytes: number): { value: number, resolutionUnit: string } {
        // ordered from largest to smallest for efficiency
        const unitOrder = [MEDIA_SIZE.GB, MEDIA_SIZE.MB, MEDIA_SIZE.KB];
        
        // Find the first unit where the content length is >= its conversion factor
        for (const unit of unitOrder) {
            const conversion = MediaFormatFilter.UNIT_CONVERSION_MAP[unit];
            if (contentLengthInBytes >= conversion) {
                return {
                    value: Math.round(contentLengthInBytes / conversion),
                    resolutionUnit: unit
                };
            }
        }
    }
}

export { MediaFormatFilter };