import { createWrapStore } from 'webext-redux';
import rootReducer from './RootReducer';
import { ReduxStates } from '../interfaces';
import MetadataStore from './reducers/MetadataStore';
import DownloadInitiatedVideosStore from './reducers/DownloadInitiatedVideosStore';
import { configureStore } from '@reduxjs/toolkit';
import { storeDataMiddleware, updateVideosStateMiddleware } from './middlewares/middlewares';
import EulaStore from './reducers/EulaAcceptanceStore';
import UIConfigurationStore from './reducers/UIConfigurationStore';

class ReduxStore {
  private store: ReturnType<typeof configureStore> | null;
  private initPromise: Promise<void> | null = null;
  constructor() {
    this.store = null;
  }

  async getInitialStates(): Promise<ReduxStates>{
    const metadataInitialState = await MetadataStore.getInitialState() || {};
    const downloadVideosInitialState = await DownloadInitiatedVideosStore.getInitialState() || {};
    const eulaAcceptanceInitialState = await EulaStore.getInitialState() || EulaStore.getDefaultState();
    const uiConfigurations = await UIConfigurationStore.getInitialState() || UIConfigurationStore.getDefaultState();
    return {
      metaData: {
        ...metadataInitialState
      },
      downloadInitiatedVideos: {
        ...downloadVideosInitialState
      },
      eulaAcceptanceDetails: {
        ...eulaAcceptanceInitialState
      },
      UIConfigurations: {
        ...uiConfigurations
      }
    } as unknown as ReduxStates
  }  

  /**
   * Initializes the store for the application. Ensures that the store is only initialized once
   * by using a promise to track the initialization process. Retrieves the initial state, creates
   * the Redux store with middleware, and wraps the store with additional functionality.
   *
   * @returns {Promise<void>} A promise that resolves once the store has been initialized.
   */
  async initStore(): Promise<void> {
    if (this.initPromise) {
      return this.initPromise;
    }
    this.initPromise = new Promise((resolve, reject) => {
      (async () => {
        try {
          const initialState = await this.getInitialStates() || {};
          const store = configureStore({
            reducer: rootReducer, 
            preloadedState: initialState, 
            middleware: (getDefaultMiddleware) => getDefaultMiddleware().concat(storeDataMiddleware, updateVideosStateMiddleware)});
          this.store = store;
          const wrapStore = createWrapStore();
          wrapStore(store);
          resolve();
        } catch (err) {
          reject(err);
        }
      })();
    });
    return this.initPromise;
  }

  /**
   * Retrieves the application store instance after ensuring it is initialized.
   * This method initializes the store if it hasn't been initialized yet,
   * and then returns the configured store instance.
   *
   * @returns {Promise<ReturnType<typeof configureStore>>} A promise that resolves to the configured store instance.
   */
  async getStore(): Promise<ReturnType<typeof configureStore>> {
    await this.initStore();
    return this.store;
  }
}

const reduxStore = new ReduxStore();
reduxStore.initStore();
export { reduxStore };

