import { StorageType } from '../constants';
class StorageManager {

  private storage: typeof chrome.storage.session | typeof chrome.storage.local;

  constructor(type: StorageType = StorageType.SESSION) {
    this.storage = type === StorageType.LOCAL ? chrome.storage.local : chrome.storage.session;
  }

  /**
   * @abstract setStorage
   * @description Helper method to assist in unit testing
   * @param storage 
   */
  setStorage(storage: chrome.storage.SessionStorageArea | chrome.storage.LocalStorageArea) {
    this.storage = storage;
  }
  
  async setItem<T>(key: string, value: T): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const data: { [key: string]: T } = {};
        data[key] = value;
        this.storage.set(data, () => {
          if (chrome.runtime.lastError) {
            reject(chrome.runtime.lastError);
          } else {
            resolve();
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  async getItem<T>(key: string): Promise<T | null> {
    return new Promise((resolve, reject) => {
      try {
        this.storage.get([key], (result) => {
          if (chrome.runtime.lastError) {
            reject(chrome.runtime.lastError);
          } else {
            resolve(result[key] ?? null);
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  async removeItem(key: string): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        this.storage.remove([key], () => {
          if (chrome.runtime.lastError) {
            reject(chrome.runtime.lastError);
          } else {
            resolve();
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  async hasItem(key: string): Promise<boolean> {
    const value = await this.getItem(key);
    return value !== null && value !== undefined;
  }

}
const sessionStore = new StorageManager(StorageType.SESSION);
const localStore = new StorageManager(StorageType.LOCAL);
export { sessionStore, localStore };
