import { combineReducers } from 'redux';
import MetadataStore from './reducers/MetadataStore';
import DownloadInitiatedVideosStore from './reducers/DownloadInitiatedVideosStore';
import EulaStore from './reducers/EulaAcceptanceStore';
import UIConfigurationStore from './reducers/UIConfigurationStore';

const rootReducer = combineReducers({
  metaData: MetadataStore.metadataReducer,
  downloadInitiatedVideos: DownloadInitiatedVideosStore.downloadInitiatedReducer,
  eulaAcceptanceDetails: EulaStore.eulaReducer,
  UIConfigurations: UIConfigurationStore.UIConfigurationReducer
});

export default rootReducer;
