import { VideoMediaInfo } from '../interfaces';
import { localStore } from '../utils/storageManager';
import { SETTING_KEYS } from '../constants';


class QueueController {
    private newVideoCallbacks: (() => void)[];
    private completedVideoCallbacks: ((videoId: string) => void)[] = [];
    private waitingVideoInfoList: VideoMediaInfo[] = [];
    
    // Metadata queue and callbacks
    private newMetaDataRequestCallbacks: ((providerName: string, videoId: string, sendResponse: (response: any) => void) => void)[] = [];
    private metadataQueue: { providerName: string, videoId: string, sendResponse: (response: any) => void }[] = [];

    constructor() {
        this.newVideoCallbacks = [];
        this.waitingVideoInfoList = [];
        // Initialize waitingVideoInfoList from storage
        localStore.getItem<VideoMediaInfo[]>(SETTING_KEYS.WAITING_QUEUE)
            .then(q => { this.waitingVideoInfoList = q || []; })
            .catch(() => { this.waitingVideoInfoList = []; });
    }

    /**
     * Reset the queueController - unit test helper method.
     */
    public async resetQueueController() {
        this.waitingVideoInfoList = [];
        await localStore.setItem(SETTING_KEYS.WAITING_QUEUE, []);
    }

    /**
     * Downloads multiple videos concurrently for fetching data and processingthem when they are fetched.
     * @param videoMediaInfos - An array of VideoInfo objects containing video and audio URLs.
     * @returns true if successful, false if an error occurred
     */
    public async enqueueVideosForDownload(videoMediaInfos: VideoMediaInfo[]): Promise<boolean> {
        try {
            // Fetch current queue from instance member
            let currentQueue: VideoMediaInfo[] = this.waitingVideoInfoList;
            // Append new videos
            const updatedList = currentQueue.concat(videoMediaInfos);
            this.waitingVideoInfoList = updatedList;
            await localStore.setItem(SETTING_KEYS.WAITING_QUEUE, updatedList);
            // Notify all registered callbacks (subscribers)
            for (const cb of this.newVideoCallbacks) {
                try { cb(); } catch (e) { console.error('QueueController callback error', e); }
            }
            return true;
        } catch (e) {
            console.error('enqueueVideosForDownload error', e);
            return false;
        }
    }
    
    /**
     * Retrieves all videos in the queue.
     * @returns An array of all videos in the queue.
     */
    public async getWaitingQueueVideos(): Promise<VideoMediaInfo[]> {
        if (!this.waitingVideoInfoList.length) return [];
        return this.waitingVideoInfoList;
    }

    /**
     * Registers a callback to be invoked when new videos are added to the queue.
     * @param callback - The callback function to register.
     */
    public registerForNewVideos(callback: () => void): void {
        this.newVideoCallbacks.push(callback);
    }

    /**
     * Registers a callback to be invoked when videos are completed.
     * @param callback - The callback function to register.
     */
    public registerForCompletedVideo(callback: (videoId: string) => void): void {
        this.completedVideoCallbacks.push(callback);
    }

    /**
     * Removes a video from the queue after download is complete and fires completed callbacks.
     * @param videoId - The video ID that has been downloaded.
     */
    public dequeueVideoAfterDownload(videoId: string): void {
        for (const cb of this.completedVideoCallbacks) {
            try { cb(videoId); } catch (e) { console.error('QueueController completed callback error', e); }
        }
    }

    /**
     * Returns the first N videos from the waiting queue , and updates localStore with the current list.
     * @param n - Number of videos to return from the front of the queue.
     */
    public async popNVideosFromWaitingQueue(n: number): Promise<VideoMediaInfo[]> {
        if (n <= 0) {
            return [];
        }
        if (this.waitingVideoInfoList.length <= n) {
            const result = this.waitingVideoInfoList.slice();
            this.waitingVideoInfoList = [];
            await localStore.setItem(SETTING_KEYS.WAITING_QUEUE, this.waitingVideoInfoList);
            return result;
        }
        const result = this.waitingVideoInfoList.slice(0, n);
        this.waitingVideoInfoList = this.waitingVideoInfoList.slice(n);
        await localStore.setItem(SETTING_KEYS.WAITING_QUEUE, this.waitingVideoInfoList);
        return result;
    }

    /**
     * Enqueue a metadata request for throttled processing
     */
    public async enqueueVideoMetadata(providerName: string, videoId: string, sendResponse: (response: any) => void): Promise<void> {
        this.metadataQueue.push({ providerName, videoId, sendResponse });
        // Notify all registered callbacks
        for (const cb of this.newMetaDataRequestCallbacks) {
          try {
            cb(providerName, videoId, sendResponse);
          } catch (e) {
            console.error("QueueController metadata callback error", e);
          }
        }
    }

    /**
     * Register a callback for new metadata requests
     */
    public registerForMetadataRequest(callback: (providerName: string, videoId: string, sendResponse: (response: any) => void) => void): void {
        this.newMetaDataRequestCallbacks.push(callback);
    }

    /**
     * Pops the first metadata request from the queue and returns it.
     */
    public async popFirstMetadataRequest(): Promise<{ providerName: string, videoId: string, sendResponse: (response: any) => void } | null> {
        if (this.metadataQueue.length === 0) {
            return null;
        }
        const firstMetaData = this.metadataQueue.shift();
        return firstMetaData || null;
    }
}

const queueController = new QueueController();
export default queueController;