import { CONSTANTS, MESSAGE_TYPES, SETTING_KEYS } from '../constants';
import { VideoMediaInfo } from '../interfaces';
import { sessionStore } from '../utils/storageManager';
import queueController from './QueueController';

class QueueWorker {
    private maxConcurrentDownloads: number = CONSTANTS.DEFAULT_MAX_CONCURRENT_DOWNLOADS;
    private activeVideoInfoList: VideoMediaInfo[] = [];
    constructor() {
        // Initialize activeVideoInfoList from session storage
        sessionStore.getItem<VideoMediaInfo[]>(SETTING_KEYS.ACTIVE_QUEUE)
            .then(q => { this.activeVideoInfoList = q ?? []; });
    }

    /**
     * Initializes the QueueWorker.
     */
    public async init(maxConcurrentDownloads: number): Promise<void> {
        // Fetch maxConcurrentDownloads from parameter
        this.maxConcurrentDownloads = maxConcurrentDownloads;
        // Register for new videos notification
        queueController.registerForNewVideos(this.onNewVideo.bind(this));
        // Register for completed videos notification
        queueController.registerForCompletedVideo(this.onVideoDownloadCompleted.bind(this));
    }

    /**
     * Called when new videos are available in the queue (from QueueController)
     */
    public async onNewVideo(): Promise<void> {
        try {
            const activeDownloadCount = this.activeVideoInfoList.length;
            const availableSlots = this.maxConcurrentDownloads - activeDownloadCount;
            if (availableSlots <= 0) return;
            // Pop up to availableSlots videos from the waiting queue
            const toDownload = await queueController.popNVideosFromWaitingQueue(availableSlots);
            if (toDownload.length > 0) {
                chrome.runtime.sendMessage({
                    type: MESSAGE_TYPES.DOWNLOAD_MEDIA,
                    videoInfo: toDownload
                });
                // Add to in-progress queue
                this.activeVideoInfoList = this.activeVideoInfoList.concat(toDownload);
                await sessionStore.setItem(SETTING_KEYS.ACTIVE_QUEUE, this.activeVideoInfoList);
            }
        } catch (error) {
            console.error('Error in onNewVideo:', error);
        }
    }


    /**
     * Called when a download is completed. Removes the completed videoId from the active queue and triggers next downloads.
     * @param videoId - The completed video ID.
     */
    public async onVideoDownloadCompleted(videoId: string): Promise<void> {
        try {
            // Use in-memory activeVideoInfoList
            this.activeVideoInfoList = this.activeVideoInfoList.filter(item => item.videoId !== videoId);
            await sessionStore.setItem(SETTING_KEYS.ACTIVE_QUEUE, this.activeVideoInfoList);
            // Trigger next downloads if any
            await this.onNewVideo();
        } catch (error) {
            console.error('Error in onVideoDownloadCompleted:', error);
        }
    }
}

const queueWorker = new QueueWorker();
export default queueWorker;