import cdnConfigManager from "../background/CDNConfigManager";
import { ACCEPTABLE_ERROR_COUNT, CONSTANTS, VIDEO_DOWNLOAD_METRICS_KEY, VIDEO_PROVIDER } from "../constants";
import { localStore, sessionStore } from "./storageManager";
import { StorageUtils } from "./storageUtils";

class MetadataValidityUtils {
    /**
     * Retrieves the acceptable error count for the system.
     * 
     * This method fetches the acceptable error count from the CDN configuration manager.
     * If the value is not defined, it falls back to a default constant value.
     * 
     * @returns A promise that resolves to the acceptable error count.
     */
    private static async getAcceptableErrorCount(): Promise<number> {
        let acceptableErrorCount = await cdnConfigManager.getAcceptableErrorCount();
        if (!acceptableErrorCount) {
            acceptableErrorCount = ACCEPTABLE_ERROR_COUNT;
        }
        return acceptableErrorCount;
    }
    /**
     * Generates a unique key to track the authentication error count for a specific video provider.
     *
     * @param videoProvider - The name of the video provider for which the authentication error key is generated.
     * @returns A string representing the unique key for the authentication error count.
     */
    private static getKeyForAuthErrorCount(videoProvider: VIDEO_PROVIDER): string {
        return `${videoProvider}-${VIDEO_DOWNLOAD_METRICS_KEY.METADATA_403_ERROR_COUNT}`;
    }

    /**
     * Generates a unique key for tracking the current error count of metadata 403 errors
     * for a specific video provider.
     *
     * @param videoProvider - The video provider for which the error count key is generated.
     * @returns A string representing the unique key for the current metadata 403 error count.
     */
    private static getKeyForCurrentErrorCount(videoProvider: VIDEO_PROVIDER): string {
        return `${videoProvider}-current-${VIDEO_DOWNLOAD_METRICS_KEY.METADATA_403_ERROR_COUNT}`;
    }

    static async getNextMetadataFetchInterval(authErrorCount: number, provider: VIDEO_PROVIDER): Promise<number> {
        let { metadataTTLInMs, killSwitchIntervalInMs } = await cdnConfigManager.getMetadataFetchIntervals(provider);
        metadataTTLInMs = metadataTTLInMs || CONSTANTS.DEFAULT_METADATA_TTL;
        killSwitchIntervalInMs = killSwitchIntervalInMs || CONSTANTS.KILL_SWITCH_TTL;
        if (!authErrorCount || authErrorCount === 0) {
            return metadataTTLInMs;
        }
        const acceptableErrorCount: number = await this.getAcceptableErrorCount();
        return authErrorCount > acceptableErrorCount ? killSwitchIntervalInMs : metadataTTLInMs;
    }

    /**
     * Retrieves the error count for the metadata 403 error kill switch from local storage.
     * If the value is not found or an error occurs during retrieval, it returns 0.
     *
     * @returns {Promise<number>} A promise that resolves to the error count for the kill switch.
     * @throws Logs an error to the console if there is an issue retrieving the value from local storage.
     * cumulative error count is the total 403 error counts
     */
    static async getCumulativeAuthErrorCount(videoProvider: VIDEO_PROVIDER): Promise<number> {
        const key: string = this.getKeyForAuthErrorCount(videoProvider);
        try {
            let count: number = await localStore.getItem(key);
            return count;
        } catch (error) {
            console.error('Error retrieving error count:', error);
            return 0;
        }
    }

    /**
     * Sets the error count for the metadata 403 error kill switch in the local storage.
     *
     * @param count - The number of errors to set for the kill switch.
     * @returns A promise that resolves when the error count is successfully set.
     * @throws Logs an error to the console if there is an issue setting the value in local storage.
     */
    static async setCumulativeAuthErrorCount(count: number, videoProvider: VIDEO_PROVIDER): Promise<void> {
        const key: string = this.getKeyForAuthErrorCount(videoProvider);
        try {
            await localStore.setItem(key, count);
        } catch (error) {
            console.error('Error setting cumulative auth error count', error);
        }
    }


    /**
     * Retrieves the current authentication error count for a given video provider.
     *
     * This method fetches the error count from a local storage mechanism using a key
     * specific to the provided video provider. If an error occurs during retrieval,
     * it logs the error and returns a default value of 0.
     *
     * @param videoProvider - The name of the video provider for which the authentication
     *                        error count is being retrieved.
     * @returns A promise that resolves to the current authentication error count.
     * This is the count of error counts for a day
     */
    static async getCurrentAuthErrorCount(videoProvider: VIDEO_PROVIDER): Promise<number> {
        const key: string = this.getKeyForCurrentErrorCount(videoProvider);
        try {
            let count: number = await localStore.getItem(key);
            return count;
        } catch (error) {
            console.error('Error retrieving error count:', error);
            return 0;
        }
    }

    /**
     * Sets the error count for HB ping in the local storage.
     *
     * @param count - The number of errors to be stored.
     * @returns A promise that resolves when the error count is successfully set.
     * @throws Logs an error to the console if there is an issue with setting the item in local storage.
     */
   static async setCurrentAuthErrorCount(count: number, videoProvider: VIDEO_PROVIDER): Promise<void> {
        const key: string = this.getKeyForCurrentErrorCount(videoProvider);
        try {
            await localStore.setItem(key, count);
        } catch (error) {
            console.error('Error setting error count:', error);
        }
    }

    /**
     * Generates a storage key for the given video ID and provider name.
     * @param provider - The provider name
     * @returns The storage key in format: videoId_providerName
     */
    private static getLastFetchedStorageKey(videoId: string, provider: VIDEO_PROVIDER): string {
        return `${videoId}_${provider}_lastfetched`;
    }

    private static getLastFetchedStorageKeyForProvider(provider: VIDEO_PROVIDER): string {
        return `${provider}_lastfetched`;
    }

    /**
     * Retrieves the timestamp of when metadata was last fetched for the given video and provider.
     * @param videoId - The video ID
     * @param provider - The provider name
     * @returns The timestamp of the last fetch, or 0 if never fetched
     */
    static async getLastFetchedForVideoId(videoId: string, provider: VIDEO_PROVIDER): Promise<number> {
        const lastFetchedStorageKey = this.getLastFetchedStorageKey(videoId, provider);
        try {
            const timestamp = await sessionStore.getItem<number>(lastFetchedStorageKey);
            return timestamp || 0;
        } catch (error) {
            console.error('Error retrieving last fetched timestamp:', error);
            return 0;
        }
    }

    /**
     * Sets the timestamp of when metadata was last fetched for the given video and provider.
     * @param videoId - The video ID
     * @param provider - The provider name
     * @param timestamp - The timestamp to store
     */
    static async setLastFetchedForVideoId(videoId: string, provider: VIDEO_PROVIDER, timestamp: number): Promise<void> {
        const lastFetchedStorageKey = this.getLastFetchedStorageKey(videoId, provider);
        
        try {
            await sessionStore.setItem(lastFetchedStorageKey, timestamp);
        } catch (error) {
            console.error('Error setting last fetched timestamp:', error);
        }
    }

    /**
     * Retrieves the last fetched timestamp for a given video provider from local storage.
     *
     * @param provider - The video provider for which the last fetched timestamp is to be retrieved.
     * @returns A promise that resolves to the last fetched timestamp as a number. 
     *          If no timestamp is found or an error occurs, it returns 0.
     * @throws Logs an error to the console if there is an issue retrieving the timestamp.
     */
    static async getLastAttempedForProvider(provider: VIDEO_PROVIDER): Promise<number> {
        const lastFetchedStorageKeyForProvider = this.getLastFetchedStorageKeyForProvider(provider);
        try {
            const timestamp = await localStore.getItem<number>(lastFetchedStorageKeyForProvider);
            return timestamp || 0;
        } catch (error) {
            console.error('Error retrieving last fetched timestamp:', error);
            return 0;
        }
    }

    /**
     * Sets the timestamp of when metadata was last fetched for the given video and provider.
     * @param videoId - The video ID
     * @param provider - The provider name
     * @param timestamp - The timestamp to store
     */
    static async setLastAttempedForProvider(provider: VIDEO_PROVIDER, timestamp: number): Promise<void> {
        const lastFetchedStorageKeyForProvider = this.getLastFetchedStorageKeyForProvider(provider);
        
        try {
            await localStore.setItem(lastFetchedStorageKeyForProvider, timestamp);
        } catch (error) {
            console.error('Error setting last fetched timestamp:', error);
        }
    }

    /**
     * Checks if metadata should be fetched based on the last fetch time and a cooldown period.
     * @param provider - The provider name
     * @param fetchIntervalMs - The period in milliseconds (default:DEFAULT_METADATA_TTL)
     * @returns True if metadata should be fetched, false otherwise
     */
    static async shouldFetchMetadata(videoId: string, provider: VIDEO_PROVIDER): Promise<boolean> {
        const errorCount: number = await MetadataValidityUtils.getCumulativeAuthErrorCount(provider);
        const fetchIntervalMs: number = await MetadataValidityUtils.getNextMetadataFetchInterval(errorCount, provider);
        let lastFetched: number;
        if (!errorCount || errorCount === 0) {
            lastFetched = await MetadataValidityUtils.getLastFetchedForVideoId(videoId, provider);
        } else {
          lastFetched = await MetadataValidityUtils.getLastAttempedForProvider(provider);
        }
        const now = Date.now();
        return (now - lastFetched) >= fetchIntervalMs;
    }

    /**
     * Resets the cumulative authentication error count for the specified provider.
     *
     * @param provider - The name of the provider for which the cumulative authentication error count should be reset.
     */
    static resetCumulativeAuthErrorCount(provider: VIDEO_PROVIDER) {
        this.setCumulativeAuthErrorCount(0, provider);
    }

    /**
     * Updates the last fetched timestamps for a specific video and its provider.
     *
     * This method sets the last fetched timestamp for the given video ID and provider,
     * as well as the last fetched timestamp for the provider itself. The timestamps
     * are set to the current time.
     *
     * @param videoId - The unique identifier of the video.
     * @param provider - The provider of the video, represented as a `VIDEO_PROVIDER` enum.
     * @returns A promise that resolves when the timestamps have been updated.
     */
    static async setLastFetchedTimestamps(videoId: string, provider: VIDEO_PROVIDER) {
        const date: number = Date.now();
        await this.setLastFetchedForVideoId(videoId, provider, date);
        await this.setLastAttempedForProvider(provider, date);
    }
    
    /**
     * Increments the authentication error counts for a given video provider.
     * 
     * This method updates two separate error counts:
     * - The cumulative authentication error count, which tracks the total number of errors.
     * - The current authentication error count, which tracks errors for a specific session or period.
     * 
     * Additionally, it updates the last fetched timestamp for the video provider.
     * 
     * @param videoProvider - The name of the video provider for which the error counts are being incremented.
     * @returns A promise that resolves when the error counts and timestamp are successfully updated.
     * @throws Logs an error to the console if an exception occurs during the update process.
     */
   static async incrementAuthErrorCounts(videoId: string, videoProvider: VIDEO_PROVIDER) {
    try {
        await this.setLastFetchedTimestamps(videoId, videoProvider);
        let cumulativeErrorCount = await this.getCumulativeAuthErrorCount(videoProvider);
        if (!cumulativeErrorCount) {
            cumulativeErrorCount = 0;
        }
        cumulativeErrorCount += 1;
        this.setCumulativeAuthErrorCount(cumulativeErrorCount, videoProvider);

        // update error count used by hb ping
        await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.METADATA_403_ERROR_COUNT);
    } catch (error) {
        console.error('Error incrementing auth error counts', error);
    }
   }
}

export { MetadataValidityUtils };