import { Middleware } from 'redux';
import { EULA_ACCEPTED_STATE_LOCAL_STORAGE_KEY, MESSAGE_TYPES, REDUX_ACTIONS, REDUX_STATE_METADATA, VIDEO_PROGRESS_STATE } from '../../constants';
import { localStore, sessionStore } from '../../utils/storageManager';
import queueControllerBG from '../../background/QueueControllerBG';
import { VideoMediaInfoManager } from '../../background/VideoMediaInfoManager';
import { DOWNLOAD_STATE, DownloadInitiatedVideosInformation, VideoMediaInfo, VideoProvider } from '../../interfaces';
import { videoDownloaderStoreService } from '../services/VideoDownloaderStoreService';
import { VideoAttributesManager } from '../../VideoAttributesManager';
import helperUtils from '../../utils/HelperUtils';
import videoDownloaderBG from '../../background/VideoDownloaderBG';
/**
* Middleware to intercept actions and store metadata in session storage.
* 
* This middleware listens for actions of type `REDUX_ACTIONS.SET_METADATA` and,
* upon detecting such an action, retrieves the current state from the Redux store
* and saves the `metaData` property to session storage using the `sessionStore` utility.
* 
* @type {Middleware}
* @param store - The Redux store instance.
* @param next - The next middleware or reducer in the chain.
* @param action - The dispatched Redux action, containing a `type` and optional `payload`.
* @returns The result of calling the next middleware or reducer.
*/
export const updateVideosStateMiddleware: Middleware = store => next => (action: { type: string; payload?: any }) => {
  const result = next(action); 
  if (action.type === REDUX_ACTIONS.VIDEO_DOWNLOAD_STARTED) {
    const formattedData: VideoMediaInfo = VideoMediaInfoManager.formatData(action.payload.format);
    queueControllerBG.enqueueVideosForDownload([formattedData]);
  }

  // Intercept cancellation actions in ProgressBar.tsx
  if (action.type === REDUX_ACTIONS.UPDATE_DOWNLOAD_STATE && 
      action.payload?.downloadState === DOWNLOAD_STATE.CANCELLATION_IN_PROGRESS) {
    // Send cancellation message directly to offscreen page with videoAttributes if available
    chrome.runtime.sendMessage({
      type: MESSAGE_TYPES.CANCEL_DOWNLOAD,
      videoMediaId: action.payload.videoId,
      videoAttributes: action.payload.videoAttributes
    });
  }

  if (
    action.type === REDUX_ACTIONS.UPDATE_DOWNLOAD_STATE ||
    action.type === REDUX_ACTIONS.SET_PROGRESS ||
    action.type === REDUX_ACTIONS.VIDEO_DOWNLOAD_STARTED ||
    action.type === REDUX_ACTIONS.SET_METADATA ||
    action.type === REDUX_ACTIONS.EULA_NOT_ACCEPT_DOWNLOAD_CLICK) {
    const state = store.getState();
    sessionStore.setItem(VIDEO_PROGRESS_STATE, state.downloadInitiatedVideos);
  }
  return result;
  // TBD Need to call the download with metadata
  // Will be done in UI integration
}

/**
* Middleware to intercept actions and store metadata in session storage.
* 
* This middleware listens for actions of type `REDUX_ACTIONS.SET_METADATA` and,
* upon detecting such an action, retrieves the current state from the Redux store
* and saves the `metaData` property to session storage using the `sessionStore` utility.
* 
* @type {Middleware}
* @param store - The Redux store instance.
* @param next - The next middleware or reducer in the chain.
* @param action - The dispatched Redux action, containing a `type` and optional `payload`.
* @returns The result of calling the next middleware or reducer.
*/
export const storeDataMiddleware: Middleware = store => next => (action: { type: string; payload?: any }) => {
  const result = next(action); 
  if (action.type === REDUX_ACTIONS.SET_METADATA) {
    const state = store.getState();
    sessionStore.setItem(REDUX_STATE_METADATA, state.metaData);
  }
  if (action.type === REDUX_ACTIONS.EULA_ACCEPTED) {
    const state = store.getState();
    // Persist the latest EULA state from the store
    localStore.setItem(EULA_ACCEPTED_STATE_LOCAL_STORAGE_KEY, state.eulaAcceptanceDetails);
    // Handle any pending downloads that were waiting for EULA acceptance
    const { downloadInitiatedVideos } = state.downloadInitiatedVideos;
    const result = Object.entries(downloadInitiatedVideos).flatMap(([videoId, items]: [string, DownloadInitiatedVideosInformation[]]) =>
      items.filter(item => item.downloadState === DOWNLOAD_STATE.EULA_NOT_ACCEPTED)
    );
    if (result && result.length > 0) {
      videoDownloaderStoreService.triggerDownload({
        format: result[0].mediaData,
        downloadSource: result[0].downloadSource
      });
    }
  }
  if (action.type === REDUX_ACTIONS.RETRY_CLICKED) {
    const videoId = action.payload.videoId;
    const state = store.getState();
    
    const { downloadInitiatedVideos } = state.downloadInitiatedVideos;
    
    const result = Object.entries(downloadInitiatedVideos).flatMap(([videoId, items]: [string, DownloadInitiatedVideosInformation[]]) =>
      items.filter(item => helperUtils.isObjectsEqual(item.videoAttributes, action.payload.videoAttributes))
    );
  
    videoDownloaderBG.getMetaDataInfo(action.payload.videoProvider, videoId).then((metadata) => {
      if (metadata) {
        videoDownloaderStoreService.setMetadata({
          videoId,
          providerName: action.payload.videoProvider,
          metadata
      });

      const format = VideoAttributesManager.getFormatFromAttributes(result[0].videoAttributes, metadata)
      videoDownloaderStoreService.triggerDownload({
        format,
        downloadSource: result[0].downloadSource
      })
      } else {
        videoDownloaderStoreService.setDownloadState({
          videoId,
          downloadState: DOWNLOAD_STATE.MEDIA_ERROR,
          videoAttributes: result[0].videoAttributes
        })
      }
    })
  }
  return result;
};