import queueController from './QueueController';
import youtubeMetaDataExtractor from '../YoutubeMetaDataExtractor';
import vimeoMetaDataExtractor from '../VimeoMetaDataExtractor';
import { CONSTANTS, VIDEO_PROVIDER, VIDEO_DOWNLOAD_METRICS_KEY } from '../constants';
import { MediaMetaDataExtractor } from '../interfaces';
import { videoDownloaderStoreService } from '../store/services/VideoDownloaderStoreService';
import iconBadgeManager from './IconBadgeManager';
import { MetadataValidityUtils } from '../utils/MetadataValidityUtils';
import helperUtils from '../utils/HelperUtils';
import { StorageUtils } from '../utils/storageUtils';

class MetadataQueueWorker {
    private isProcessing = false;
    private metadataFetchDelay = CONSTANTS.DEFAULT_FETCH_METADATA_IN_MILLISECONDS;
    private metaDataExtractors: Map<string, MediaMetaDataExtractor>;
    // map for last request timestamp per provider
    private lastRequestTimestamp: Map<string, number> = new Map();

    constructor() {
        this.metaDataExtractors = new Map<string, MediaMetaDataExtractor>([
            [VIDEO_PROVIDER.YOUTUBE, youtubeMetaDataExtractor],
            [VIDEO_PROVIDER.VIMEO, vimeoMetaDataExtractor]
        ]);
        this.processQueue.bind(this);
    }

    /**
     * Initializes the QueueWorker.
     */
    public async init(metadataFetchDelay:number): Promise<void> {
        this.metadataFetchDelay = metadataFetchDelay;
        queueController.registerForMetadataRequest(async () => {
            await this.processQueue();
        });

    }

    private async waitIfNeeded(providerName: string) {
        const lastTs = this.lastRequestTimestamp.get(providerName) || 0;
        const now = Date.now();
        const wait = Math.max(0, this.metadataFetchDelay - (now - lastTs));
        if (wait > 0) {
            await new Promise(res => setTimeout(res, wait));
        }
    }

    private async processQueue() {
        if (this.isProcessing) return;
        this.isProcessing = true;
        try {
            let nextRequest = await queueController.popFirstMetadataRequest();
            while (nextRequest) {
                let metaData = null;
                const shouldFetch = await MetadataValidityUtils.shouldFetchMetadata(nextRequest.videoId, nextRequest.providerName as VIDEO_PROVIDER);
                if (!shouldFetch) {
                    metaData = await videoDownloaderStoreService.getMetadataForVideoId(nextRequest.videoId, nextRequest.providerName);
                    if (metaData) {
                        nextRequest.sendResponse({ success: true, data: metaData });
                    } else {
                        nextRequest.sendResponse({ success: false, data: metaData });
                    }
                }
                else {
                    await this.handleMetadataRequest(nextRequest);
                }
                nextRequest = await queueController.popFirstMetadataRequest();
            }
        } finally {
            this.isProcessing = false;
        }
    }

    private async handleMetadataRequest(request: { providerName: string, videoId: string, sendResponse: (response: any) => void }) {
        const { providerName, videoId, sendResponse } = request;
        let metaData: any = null;
        try {
            await this.waitIfNeeded(providerName);
            metaData = await this.metaDataExtractors.get(providerName)?.getMetadataInfo(videoId);
            if (metaData) {
                await videoDownloaderStoreService.setMetadata({
                    videoId,
                    providerName,
                    metadata: metaData
                });
                await iconBadgeManager.updateIconAndBadge();
                await MetadataValidityUtils.setLastFetchedForVideoId(request.videoId, request.providerName as VIDEO_PROVIDER, Date.now());
                await MetadataValidityUtils.resetCumulativeAuthErrorCount(request.providerName as VIDEO_PROVIDER);
                sendResponse({ success: true, data: metaData });
            } else {
                sendResponse({ success: false, data: null });
            }
        } catch (error) {
            sendResponse({ success: false, data: null });
        }
        // Update last request timestamp for this provider in memory
        this.lastRequestTimestamp.set(providerName, Date.now());
        // Increment telemetry counts for played and non-supported videos (if applicable)
        if(this.metaDataExtractors.get(providerName)?.isLiveVideoApplicable === false) {
            // Increment played videos count
            await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.VIDEOS_PLAYED_COUNT);
            // Only increment non-supported videos count if metadata is null
            if (!metaData) {
                await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.NOT_SUPPORTED_VIDEOS_COUNT);
            }
        }
    }
}

const metadataQueueWorker = new MetadataQueueWorker();
export default metadataQueueWorker;
