import { REDUX_ACTIONS, VIDEO_PROGRESS_STATE } from "../../constants";
import {  DOWNLOAD_STATE, DownloadInitiatedVideosReduxState, videoAttributes, VideoProviderMetadataMap } from "../../interfaces";
import helperUtils from "../../utils/HelperUtils";
import { sessionStore } from "../../utils/storageManager";
import { VideoAttributesManager } from "../../VideoAttributesManager";
class DownloadInitiatedVideosStore {
      /**
       * Retrieves the initial state for the metadata store.
       *
       * @returns {MetadataReduxState} The initial state object containing default values for metadata.
       */
      static getDefaultState(): DownloadInitiatedVideosReduxState {
        return {
          downloadInitiatedVideos: {},
        }
      }

      /**
       * Retrieves the initial state for video provider metadata from the session store.
       * 
       * @returns {Promise<DownloadInitiatedVideosReduxState>} A promise that resolves to the video provider metadata map.
       */
      static async getInitialState(): Promise<DownloadInitiatedVideosReduxState> {
        let downloadInitiatedVideos: DownloadInitiatedVideosReduxState = await sessionStore.getItem(VIDEO_PROGRESS_STATE);
        if (!downloadInitiatedVideos) {
          downloadInitiatedVideos = DownloadInitiatedVideosStore.getDefaultState()
        }
        return downloadInitiatedVideos;
      }

      /**
       * Reducer function for managing metadata state in the Redux store.
       * 
       * @param state - The current state of the metadata store. Defaults to the initial state
       *                provided by `MetadataStore.getInitialState()`.
       * @param action - The dispatched Redux action containing a `type` and `payload`.
       * 
       * @returns The updated state based on the action type and payload.
       * 
       * ### Action Types:
       * - `REDUX_ACTIONS.SET_METADATA`: Updates the metadata for a specific video and provider.
       *   - `action.payload.videoId` - The ID of the video whose metadata is being updated.
       *   - `action.payload.metadata` - The metadata object to merge with the existing metadata.
       *   - `action.payload.providerName` - The name of the provider associated with the metadata.
       * 
       * ### State Structure:
       * - `state.metadataValues`: An object where keys are provider names and values are objects
       *   containing video IDs mapped to their respective metadata.
       * 
       * ### Behavior:
       * - If the provider or video ID does not exist in the current state, they will be added.
       * - Existing metadata for a video will be merged with the new metadata provided in the action payload.
       * - If the action type is not recognized, the state will remain unchanged.
       */
      static downloadInitiatedReducer(state = DownloadInitiatedVideosStore.getDefaultState(), action: { type: string; payload: any }) {
        // TBD Need to update other states too , should be done in intengration
        switch (action.type) {
          case REDUX_ACTIONS.VIDEO_DOWNLOAD_STARTED:
            const { format, downloadSource } = action.payload;
            const existingItems = state.downloadInitiatedVideos[format.videoDetails.videoId] || [];
            const videoAttrib = VideoAttributesManager.getVideoAttributes(format);
            const updatedItems = helperUtils.filterNotStartedVideos(existingItems, videoAttrib);
           
            return {
              ...state,
              downloadInitiatedVideos: {
                ...state.downloadInitiatedVideos,
                [format.videoDetails.videoId]: [
                  ...(updatedItems || []),
                  {
                    downloadState: DOWNLOAD_STATE.STARTED,
                    progressPercentage: 0,
                    videoAttributes: VideoAttributesManager.getVideoAttributes(format),
                    downloadSource: downloadSource
                  }
                ]
              }
            };
          
          case REDUX_ACTIONS.SET_METADATA:
            return {
              ...state,
              downloadInitiatedVideos: {
                ...state.downloadInitiatedVideos,
                [action.payload.videoId]: state.downloadInitiatedVideos[action.payload.videoId]
                  ? state.downloadInitiatedVideos[action.payload.videoId]
                  : [
                      {
                        downloadState: DOWNLOAD_STATE.NOT_STARTED,
                      },
                    ]
              }
            }

          case REDUX_ACTIONS.SET_PROGRESS:
            const { progressPercentage } = action.payload;
            const videoid: string = action.payload.videoId;
            const attributes: videoAttributes = helperUtils.getVideoAttributeFromId(videoid);
            const id: string = helperUtils.getVideoId(videoid);
            return {
              ...state,
              downloadInitiatedVideos: {
                ...state.downloadInitiatedVideos,
                [id]: state.downloadInitiatedVideos[id]?.map(item =>
                  helperUtils.isObjectsEqual(item.videoAttributes, attributes)
                    ? { ...item, progressPercentage }
                    : item
                )
              }
            }
          
          case REDUX_ACTIONS.UPDATE_DOWNLOAD_STATE:
            const { downloadState, videoAttributes } = action.payload;
            
            // Special handling for cancellation - remove specific video entry based on videoAttributes
            if (downloadState === DOWNLOAD_STATE.CANCELLED) {
              
              // If videoAttributes is null, remove all entries for this videoId
              if (!videoAttributes) {
                const { [action.payload.videoId]: _, ...remainingVideos } = state.downloadInitiatedVideos;
                return {
                  ...state,
                  downloadInitiatedVideos: remainingVideos
                };
              }
              
              // If videoAttributes is provided, only remove entries with matching attributes
              const existingItems = state.downloadInitiatedVideos[action.payload.videoId] || [];
              const updatedItems = existingItems.map(item => {
                if (helperUtils.isObjectsEqual(item.videoAttributes, videoAttributes)) {
                  return {
                    ...item,
                    downloadState: DOWNLOAD_STATE.NOT_STARTED
                  };
                }
                return item;
              });
              
              // Otherwise, keep the filtered items
              return {
                ...state,
                downloadInitiatedVideos: {
                  ...state.downloadInitiatedVideos,
                  [action.payload.videoId]: updatedItems
                }
              };
            }
            
            // Normal case - update specific item
            return {
              ...state,
              downloadInitiatedVideos: {
              ...state.downloadInitiatedVideos,
              [action.payload.videoId]: [
                ...state.downloadInitiatedVideos[action.payload.videoId]?.map(item =>
                helperUtils.isObjectsEqual(item.videoAttributes, videoAttributes)
                  ? { ...item, downloadState }
                  : item
                ),
                ...(downloadState === DOWNLOAD_STATE.COMPLETED
                ? [{ downloadState: DOWNLOAD_STATE.NOT_STARTED }]
                : [])
              ]
              }
            }

          case REDUX_ACTIONS.EULA_NOT_ACCEPT_DOWNLOAD_CLICK:
            const formatDetails = action.payload.format;
            const eulaDownloadSource = action.payload.downloadSource;
            const updatedVideos = Object.fromEntries(
              Object.entries(state.downloadInitiatedVideos || {}).map(([key, entry]) => [
                key,
                entry.map(item => 
                  item.downloadState === DOWNLOAD_STATE.EULA_NOT_ACCEPTED 
                    ? { ...item, downloadState: DOWNLOAD_STATE.NOT_STARTED } 
                    : item
                )
              ])
            );
            
            return {
              ...state,
              downloadInitiatedVideos: {
                ...updatedVideos,
                [formatDetails.videoDetails.videoId]: [{
                  downloadState: DOWNLOAD_STATE.EULA_NOT_ACCEPTED,
                  mediaData: formatDetails,
                  downloadSource: eulaDownloadSource
                }]
              }
            }
          
          case REDUX_ACTIONS.RETRY_CLICKED:
            const existingEntries = state.downloadInitiatedVideos[action.payload.videoId] || [];
            const failedIndex = helperUtils.getFailedVideoIndex(existingEntries, action.payload.videoAttributes);
            let updatedEntries = existingEntries;
            if (failedIndex !== -1) {
              updatedEntries = existingEntries.map((entry, idx) =>
                idx === failedIndex
                  ? {
                      ...entry,
                      downloadState: DOWNLOAD_STATE.STARTED,
                      progressPercentage: 0,
                      videoAttributes: entry.videoAttributes
                    }
                  : entry
              );
            }
            return {
              ...state,
              downloadInitiatedVideos: {
                ...state.downloadInitiatedVideos,
                [action.payload.videoId]: updatedEntries,
              }
            };
                      
          default:
          return state;
        }
      };
    }
    export default DownloadInitiatedVideosStore;
  