class ApplicationSettingsManager {
    /**
     * Determines whether telemetry is enabled for the application.
     *
     * @returns {boolean} `true` if telemetry is enabled, otherwise `false`.
     */
    async isTelemetryEnabled(): Promise<boolean> {
        let isEnabled:boolean = false; //default to false
        try {
            // @ts-ignore
            if (chrome?.avast?.stats?.statsEnabled) {
              // @ts-ignore
                return await chrome.avast.stats.statsEnabled();
            } else {
              return isEnabled;
            }
        } catch (error) {
            console.error('Error in isTelemetryEnabled:', error);
            return isEnabled;
        }
    }
    /**
   * Retrieves the application settings related to telemetry.
   *
   * @returns An object containing telemetry-related settings.
   * @property isTelemetryEnabled - An asynchronous function that checks if telemetry is enabled.
   * @returns A promise that resolves to a boolean indicating whether telemetry is enabled.
   */
  getApplicationSettings() {
    return {
      isTelemetryEnabled: this.isTelemetryEnabled
    }
  }
}
const applicationSettingsManager = new ApplicationSettingsManager();
export { applicationSettingsManager };