import { TelemetryTracker } from "./TelemetryTracker";
import { Logger } from "./Logger";
import { TelemetryEventNames } from "./interfaces";
import { ERROR, WARNING } from "./constants";
class TrackingServerAnalyticsFacade {
    constructor(initParams, appTelemetrySettings, appDynamicTelemetrySettings) {
        this._telemetryTracker = new TelemetryTracker();
        this._telemetryTracker.init(initParams, appTelemetrySettings, appDynamicTelemetrySettings);
        this._logger = new Logger(this._telemetryTracker.getBuildType());
    }
    //sends telemetry event irrespective of user's consent 
    forceSendImmediate(telemetryEvent) {
        return this._telemetryTracker.forceSendImmediate(telemetryEvent);
    }
    //sends telmetry event only if user's consent is true
    sendEvent(telemetryEvent) {
        return this._telemetryTracker.sendEvent(telemetryEvent);
    }
    //error logs can be sent only with the user consent
    sendErrorLog(errorLog) {
        const extnLogEvent = {
            event: TelemetryEventNames.extnLogs,
            type: ERROR,
            value: errorLog,
        };
        this._logger.error(errorLog);
        return this._telemetryTracker.sendEvent(extnLogEvent);
    }
    //warning logs can be sent only with the user consent
    sendWarningLog(warningLog) {
        const extnLogEvent = {
            event: TelemetryEventNames.extnLogs,
            type: WARNING,
            value: warningLog,
        };
        this._logger.warn(warningLog);
        return this._telemetryTracker.sendEvent(extnLogEvent);
    }
    sendCustomEvent(reqUrl, telemetryEvent) {
        this._telemetryTracker.sendCustomEvent(reqUrl, telemetryEvent);
    }
    // returns the Common Attributes of the extension
    async getCommonAttributes() {
        return await this._telemetryTracker.getCommonAttributes();
    }
}
export default TrackingServerAnalyticsFacade;
