import Bowser from "bowser";
import { INTERNAL_API_KEYS } from "./constants";
/**
 * safeFetch - utility function to send http request
 * @param url - to which the http request should be sent
 * @param options - this object specifies varies attributes for the http request
 * @param timeoutMs - in case if the request takes longer time, error should be thrown
 * @returns
 */
export async function safeFetch(url, options = {}, // Optional options object for fetch
timeoutMs = 3000 // Default timeout of 3 seconds
) {
    return new Promise((resolve, reject) => {
        const timeoutid = setTimeout(function () {
            reject(new Error("Request timed out for " + url));
        }, timeoutMs);
        fetch(url, options).then((response) => {
            clearTimeout(timeoutid);
            resolve(response);
        }).catch((error) => {
            clearTimeout(timeoutid);
            reject(error);
        });
    });
}
/**
* getCommonAttributes - utility function to get browser name if its part of Gen brand
* @returns string name of browser
*/
export async function getGenBrowserName() {
    const avastChromeApi = chrome.avast;
    return new Promise((resolve) => {
        try {
            avastChromeApi.getStatsValue(INTERNAL_API_KEYS.BROWSER_NAME, (key, value) => {
                resolve(value);
            });
        }
        catch (error) {
            resolve(''); // resolving to empty string in case of error
        }
    });
}
/**
 * getCommonAttributes - utility function to get common attributes for all the events
 * @returns object containing common attributes for all the events
 */
export async function getCommonAttributes() {
    let navigatorObj = null;
    // Check if navigator is available in the global scope
    if (typeof window !== "undefined" && window.navigator) {
        navigatorObj = window.navigator;
    }
    else if (typeof navigator !== "undefined") {
        // If window is not available, check if navigator is available in the global scope
        navigatorObj = navigator;
    }
    else {
        return null; // Return null if neither is available
    }
    if (!navigatorObj || !navigatorObj.userAgent) {
        return null;
    }
    const browserInfo = Bowser.getParser(navigatorObj.userAgent);
    const genBrowserName = await getGenBrowserName();
    const browserName = genBrowserName ? genBrowserName : browserInfo.getBrowserName();
    const browserVersion = browserInfo.getBrowserVersion();
    const osName = browserInfo.getOSName();
    const osVersion = browserInfo.getOSVersion();
    const paltformType = browserInfo.getPlatformType();
    const commonAttributes = {
        browser: browserName ? browserName : null, //assigning null as default for handling UA spoofing use case.
        browser_version: browserVersion ? browserVersion : null,
        browser_language: navigatorObj.language ? navigatorObj.language : null,
        os: osName ? osName : null,
        os_version: osVersion ? osVersion : null,
        client_timestamp: Date.now(),
        platform: paltformType ? paltformType : null
    };
    return commonAttributes;
}
