import { REDUX_ACTIONS, REDUX_STATE_METADATA } from "../../constants";
import {  MetadataReduxState } from "../../interfaces";
import { sessionStore } from "../../utils/storageManager";
class MetadataStore {
      /**
       * Retrieves the initial state for the metadata store.
       *
       * @returns {MetadataReduxState} The initial state object containing default values for metadata.
       */
      static getDefaultState(): MetadataReduxState {
        return {
          metadataValues: {},
        }
      }

      /**
       * Retrieves the initial state for video provider metadata from the session store.
       * 
       * @returns {Promise<MetadataReduxState>} A promise that resolves to the video provider metadata map.
       */
      static async getInitialState(): Promise<MetadataReduxState> {
        let metadataState: MetadataReduxState = await sessionStore.getItem(REDUX_STATE_METADATA);
        if (!metadataState) {
          metadataState = MetadataStore.getDefaultState()
        }
        return metadataState;
      }

      /**
       * Reducer function for managing metadata state in the Redux store.
       * 
       * @param state - The current state of the metadata store. Defaults to the initial state
       *                provided by `MetadataStore.getInitialState()`.
       * @param action - The dispatched Redux action containing a `type` and `payload`.
       * 
       * @returns The updated state based on the action type and payload.
       * 
       * ### Action Types:
       * - `REDUX_ACTIONS.SET_METADATA`: Updates the metadata for a specific video and provider.
       *   - `action.payload.videoId` - The ID of the video whose metadata is being updated.
       *   - `action.payload.metadata` - The metadata object to merge with the existing metadata.
       *   - `action.payload.providerName` - The name of the provider associated with the metadata.
       * 
       * ### State Structure:
       * - `state.metadataValues`: An object where keys are provider names and values are objects
       *   containing video IDs mapped to their respective metadata.
       * 
       * ### Behavior:
       * - If the provider or video ID does not exist in the current state, they will be added.
       * - Existing metadata for a video will be merged with the new metadata provided in the action payload.
       * - If the action type is not recognized, the state will remain unchanged.
       */
      static metadataReducer(state = MetadataStore.getDefaultState(), action: { type: string; payload: any }) {
        switch (action.type) {
          case REDUX_ACTIONS.SET_METADATA:
            const { videoId, metadata, providerName } = action.payload;

            const existingProviderData = state.metadataValues[providerName] || {};
            const existingVideoMetaData = existingProviderData[videoId] || {};
      
            return {
              ...state,
              metadataValues: {
                ...state.metadataValues,
                [providerName]: {
                  ...existingProviderData,
                  [videoId]: {
                    ...existingVideoMetaData,
                    ...metadata
                  }
                }
              }
            };
      
          default:
          return state;
        }
      };
    }
    export default MetadataStore;
  