import { localStore } from "./storageManager";

class StorageUtils {
  /**
     * Increments a specific metrics count in local storage for telemetry tracking.
     * This is a common utility function to avoid code duplication when incrementing
     * various video download metrics counts.
     * 
     * @param metricsKey - The key from VIDEO_DOWNLOAD_METRICS_KEY to increment
     * @returns A promise that resolves to void
     */
  static async incrementMetricsCount(metricsKey: string): Promise<void> {
    try {
        const currentCount = await localStore.getItem<number>(metricsKey) ?? 0;
        await localStore.setItem(metricsKey, currentCount + 1);
    } catch (error) {
        console.error(`Error incrementing metrics count for key: ${metricsKey}`, error);
    }
  }
}
export { StorageUtils };