import { DOWNLOAD_STATE, MediaProcessor, THEMES } from '../interfaces';
import { OFFSCREEN_MESSAGE_TYPES, VIDEO_PROVIDER, VIDEO_PROVIDERS_REQUIRE_URL_CHANGE_LISTENER, METADATA_NAME_SEPERATOR, SUPPORTED_HOSTS, INTERNAL_API_KEYS, BRAND_NAME, VIDEO_DOWNLOAD_METRICS_KEY } from '../constants';
import type { CDNConfigRules, DownloadInitiatedVideosInformation, videoAttributes } from '../interfaces';

class HelperUtils {
    /**
     * Initializes the FFmpeg library by loading its core and WASM files.
     * @returns A promise that resolves when FFmpeg is successfully initialized.
     */

    async sendStateMessage(videoId: string, attributes: videoAttributes, state: DOWNLOAD_STATE): Promise<void> {
        const payload = {
            videoId: videoId,
            downloadCompletionStatus: state,
            videoAttributes: attributes
        };
        chrome.runtime.sendMessage({
            type: OFFSCREEN_MESSAGE_TYPES.DOWNLOAD_COMPLETION_STATUS,
            payload: payload
        });
    }

    /**
     * Converts a Base64 string to a Blob.
     * @param base64 - The Base64 string to convert.
     * @param mimeType - The MIME type of the resulting Blob.
     * @returns A Blob created from the Base64 string.
     */
    public base64ToBlob(base64: string, mimeType: string): Blob {
        const byteCharacters = atob(base64);
        const byteArrays = [];

        for (let i = 0; i < byteCharacters.length; i++) {
            byteArrays.push(byteCharacters.charCodeAt(i));
        }

        return new Blob([new Uint8Array(byteArrays)], { type: mimeType });
    }
    
    
    /**
     * Determines the video provider, domParsingRules, videoIdRegex for the current hostname.
     * @param rules - The rules object from config/CDN
     * @returns { provider: VIDEO_PROVIDER, domParsingRules: string[], videoIdRegex: string }
     */
    getProviderAndDomParsingRules(rules: CDNConfigRules): { provider: VIDEO_PROVIDER, domParsingRules: string[], videoIdRegex: string } {
        const hostname = window.location.hostname;
        const providers = rules.videoProviders || {};
        const providerKey = Object.keys(providers).find(key =>
            Array.isArray(providers[key].supportedHostnames) &&
            providers[key].supportedHostnames.some((pattern: string) => {
                const domain = pattern.slice(2);
                return hostname === domain || hostname.endsWith('.' + domain);
            })
        );
        const provider = providerKey as VIDEO_PROVIDER;
        const providerObj = providers[provider];
        let videoIdRegex: string = '';
        let domParsingRules: string[] = [];
        if (providerObj?.urlParsingRules && Array.isArray(providerObj.urlParsingRules) && providerObj.urlParsingRules.length > 0) {
            videoIdRegex = providerObj.urlParsingRules[0].validator;
        }
        if (providerObj?.domParsingRules) {
            domParsingRules = providerObj.domParsingRules;
        }
        // Add future providers here
        return { provider, domParsingRules, videoIdRegex };
    }

    /**
     * Constructs a full URL by combining a base path and a relative URL.
     *
     * @param basePath - The base path or origin to use as the starting point of the URL.
     * @param url - The relative URL to append to the base path.
     * @returns The fully constructed URL object.
     */
    constructFullUrl(basePath: string, url: string): URL {
        const base = new URL(url);
        return new URL(basePath, base);
    }

    /**
     * Checks if a given hostname is a supported video provider (YouTube, Vimeo, etc).
     * @param hostname - The hostname to check (e.g., 'www.youtube.com')
     * @returns true if supported, false otherwise
     */
    public isSupportedVideoProviderHostname(hostname: string): boolean {
        return VIDEO_PROVIDERS_REQUIRE_URL_CHANGE_LISTENER.some((domain) => {
            return hostname === domain || hostname.endsWith('.' + domain);
        });
    }

    /**
     * Generates a new GUID (Globally Unique Identifier) in the standard UUID v4 format.
     *
     * The GUID is created using a combination of the current timestamp and random values,
     * ensuring uniqueness.
     *
     * @returns {string} A string representing the newly generated GUID in the format
     * `xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx`.
     */
    createNewGuid(): string {
        let date: number = new Date().getTime()
        const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
          const r = (date + Math.random() * 16) % 16 | 0
          date = Math.floor(date / 16)
          return (c == 'x' ? r : (r & 0x7) | 0x8).toString(16)
        })
        return uuid
    }

    /**
     * Generates a unique key based on the provided video ID and video attributes.
     *
     * @param videoId - The unique identifier for the video.
     * @param attributes - An object containing video attributes.
     * @returns A string representing the unique key composed of the video ID and the first key-value pair of the attributes.
     */
    getKey(videoId: string, attributes: videoAttributes): string {
        const attributeString = Object.entries(attributes)
            .map(([key, value]) => `${key}${METADATA_NAME_SEPERATOR}${value}`)
            .join(METADATA_NAME_SEPERATOR);
        return `${videoId}${METADATA_NAME_SEPERATOR}${attributeString}`;
    }

    /**
     * Extracts video attributes from a given video ID string.
     *
     * The ID string is expected to follow a specific format where attributes
     * are separated by slash (`/`). This method splits the ID string and
     * constructs a `videoAttributes` object using the extracted values.
     *
     * @param id - The video ID string in the format `prefix/attribute/key/attribute/value`.
     * @returns A `videoAttributes` object containing the extracted key-value pair.
     *
     * @example
     * ```typescript
     * const id = "video/quality/HD";
     * const attributes = getVideoAttributeFromId(id);
     * console.log(attributes); // { quality: ["HD"] }
     * ```
     */
    getVideoAttributeFromId(id: string): videoAttributes {
        const parts = id.split(METADATA_NAME_SEPERATOR);
        const attribute: videoAttributes = {};
        for (let i = 1; i < parts.length; i += 2) {
            attribute[parts[i]] = isNaN(+parts[i + 1]) ? parts[i + 1] : +parts[i + 1];
        }
        return attribute;
    }

    /**
     * Extracts the video ID from a given string by splitting it at the slash ('/') 
     * and returning the first segment.
     *
     * @param videoid - The input string containing the video ID, typically in the format "id-suffix".
     * @returns The extracted video ID, which is the first segment of the input string.
     */
    getVideoId(videoid: string): string {
        const stringArray = videoid.split(METADATA_NAME_SEPERATOR);
        return stringArray[0];
    }

    /**
     * Compares two objects for deep equality.
     *
     * @param sourceObject - The first object to compare.
     * @param targetObject - The second object to compare.
     * @returns `true` if the objects are deeply equal, otherwise `false`.
     *
     * @remarks
     * - This function performs a deep comparison of the objects, including nested properties.
     * - If either of the inputs is not an object or is `null`, the function returns `false`.
     * - The comparison considers both the keys and their corresponding values.
     */
    isObjectsEqual(sourceObject: Object, targetObject: Object) {
        if (sourceObject === targetObject) return true;
      
        if (
          typeof sourceObject !== 'object' || sourceObject === null ||
          typeof targetObject !== 'object' || targetObject === null
        ) return false;
      
        const keys1 = Object.keys(sourceObject);
        const keys2 = Object.keys(targetObject);
        if (keys1.length !== keys2.length) return false;
        return keys1.every(key => this.isObjectsEqual(sourceObject[key], targetObject[key]));
      }

    /**
     * Retrieves the details of a browser tab using its tab ID.
     *
     * @param tabId - The unique identifier of the browser tab to retrieve.
     * @returns A promise that resolves to the `chrome.tabs.Tab` object containing details of the tab.
     * @throws Will throw an error if the tab with the specified ID does not exist or cannot be accessed.
     */
    async getUrlFromTabId(tabId: number): Promise<string> {
        const tab: chrome.tabs.Tab = await chrome.tabs.get(tabId);
        return tab?.url;
    }

    /**
     * Retrieves the hostname of the current active tab.
     *
     * @returns A promise that resolves to the hostname of the current active tab, or empty string if not available.
     * @throws Will throw an error if the current tab cannot be accessed.
     */
    async getCurrentTabHostname(): Promise<string> {
        try {
            const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
            if (tabs[0]?.url) {
                const url = new URL(tabs[0].url);
                return url.hostname;
            }
            return '';
        } catch (error) {
            console.error('Error getting current tab hostname:', error);
            return '';
        }
    }

    /**
     * Checks if the given hostname is supported for video downloading.
     *
     * @param hostname - The hostname to check.
     * @returns `true` if the hostname is in the list of supported hosts, otherwise `false`.
     */
    isVideoDownloadSupportedHostname(hostname: string): boolean {
        return SUPPORTED_HOSTS.includes(hostname);
    }

    /**
     * Retrieves the browser version using the Avast internal API.
     *
     * @returns {Promise<any>} A promise that resolves with the browser version as a string.
     *                         If an error occurs, the promise is rejected with the error.
     *
     * @throws Will reject the promise if there is an error accessing the Avast API.
     */
    async getBrowserVersion () : Promise<any> {
        return new Promise((resolve, reject) => {
            try {
                (chrome as any).avast.getStatsValue(INTERNAL_API_KEYS.BROWSER_VERSION, (key: string, value: string) => {
                    resolve(value);
                });
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Function to get browser brand using chrome.avast api.
     *
     * @returns {Promise<any>} A promise that resolves with the browser name as a string.
     *                         If an error occurs, the promise is rejected with the error.
     *
     * @throws Will reject the promise if there is an error accessing the Avast API.
     */
    async getBrowserBrand () : Promise<string> {
        return new Promise((resolve, reject) => {
            try {
                (chrome as any).avast.getStatsValue(INTERNAL_API_KEYS.BROWSER_NAME, (key: string, value: string) => {
                    const browserName = value ? value.toLowerCase() : '';
                    switch (true) {
                        case browserName.includes(BRAND_NAME.AVAST):
                            resolve(BRAND_NAME.AVAST);
                        case browserName.includes(BRAND_NAME.AVG):
                            resolve(BRAND_NAME.AVG);
                        case browserName.includes(BRAND_NAME.AVIRA):
                            resolve(BRAND_NAME.AVIRA);
                        case browserName.includes(BRAND_NAME.CCLEANER):
                            resolve(BRAND_NAME.CCLEANER);
                        case browserName.includes(BRAND_NAME.NORTON):
                            resolve(BRAND_NAME.NORTON);
                        default:
                            resolve('');    
                    }
                });
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Retrieves the user ID using the Avast Chrome extension API.
     *
     * This method interacts with the Avast Chrome extension to fetch the user ID
     * associated with the current session. It uses the `getStatsValue` method
     * provided by the extension to retrieve the value of the specified key.
     *
     * @returns {Promise<any>} A promise that resolves with the user ID as a string,
     * or rejects with an error if the operation fails.
     *
     * @throws Will reject the promise if an error occurs while accessing the Avast API.
     */
    async getUserId() : Promise<string> {
        return new Promise((resolve, reject) => {
            try {
                (chrome as any).avast.getStatsValue(INTERNAL_API_KEYS.USER_ID, (key: string, value: string) => {
                    resolve(value);
                });
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Checks if telemetry is opted in by the user in the borwser
     *
     * @returns {Promise<boolean>} A promise that resolves with opted in status of telemetry enabled or not.
     *
     * @throws Will reject the promise if an error occurs while accessing the Avast API.
     */
    async isBrowserTelemetryEnabled(): Promise<boolean> {
        return new Promise((resolve, reject) => {
            try {
                const isTelemetryEnabled = (chrome as any).avast.stats.statsEnabled();
                resolve(isTelemetryEnabled);
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Checks if dark mode is enabled in the browser
     *
     * @returns {Promise<boolean>} A promise that resolves with boolean whether dark mode is enabled or not
     *
     * will resolve to false(default) in case of error
     */
    async isBrowserDarkThemeEnabled(): Promise<boolean> {
        return new Promise((resolve, reject) => {
            try {
                const isDarkThemeEnabled = (chrome as any).avast.themes.getDarkModeEnabled();
                resolve(isDarkThemeEnabled);
            } catch (error) {
                resolve(false); // resolving to false in case of error
            }
        });
    }

    /**
     * Function to return current browser theme, whether its dark or light
     *
     * @returns {Promise<THEMES>} A promise that resolves with THEMES enum which has value light or dark
     *
     * will resolve to light(default) in case of error
     */
    async getCurrentBrowserTheme(): Promise<THEMES> {
        try {
            const isDarkThemeEnabled = await this.isBrowserDarkThemeEnabled();
            return isDarkThemeEnabled ? THEMES.DARK : THEMES.LIGHT;
        } catch (error) {
            return THEMES.LIGHT; // returning default theme in case of error
        }
    }

    /**
     * Retrieves the midex value from the Secure Browser, since it is supported in Windows alone and
     * it will throw error for other os, so resolving with empty string in error case
     * 
     * @returns {Promise<string>} A promise that resolves with opted in status of telemetry enabled or not.
     *
     * @throws Will reject the promise if an error occurs while accessing the Avast API.
     */
    async getMidexValue(): Promise<string> {
        return new Promise((resolve, reject) => {
            try {
                (chrome as any).avast.getStatsValue(INTERNAL_API_KEYS.MIDEX, (value: string) => {
                    resolve(value);
                });
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * This function formats date object to yyyy-mm-dd format
     * @param date - the date onj which has to be converted to this format
     * 
     * @returns {string} string od date representation in yyyy-mm-dd-format
     */
    formatDateToYYYYMMDD(date: Date): string {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0'); // Months are 0-based
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    /**
   * Helper to get from local storage
   * @param key - the key which need to be retrived from local storage
   * 
   * @returns {Promise<any>} A promise that resolves with result of type any from storage
   * 
   * @throws Will reject the promise if an error occurs in retrieval.
   */
    getStorageValues(key): Promise<any> {
        return new Promise((resolve, reject) => {
            chrome.storage.local.get([
                key,
            ], (result) => {
                if (chrome.runtime.lastError) {
                    reject(chrome.runtime.lastError);
                } else {
                    resolve(result);
                }
            });
        });
    }

    /**
     * Filters out videos that are either in the "EULA_NOT_ACCEPTED" or "NOT_STARTED" download states.
     *
     * @param videoArray - An array of video objects to be filtered.
     * @returns An array of video objects that do not have a download state of "EULA_NOT_ACCEPTED" or "NOT_STARTED".
     */
    filterNotStartedVideos(videoArray: DownloadInitiatedVideosInformation[], videoAttributes: videoAttributes) {
        return videoArray.filter(
            item => item.downloadState !== DOWNLOAD_STATE.EULA_NOT_ACCEPTED && item.downloadState !== DOWNLOAD_STATE.NOT_STARTED &&
            !this.isObjectsEqual(item.videoAttributes, videoAttributes)
        )
    }

    /**
     * Retrieves the index of a video entry that has failed to download due to a media or service error.
     * The function checks for matching video attributes and specific download states to identify the failed video.
     *
     * @param entries - An array of `DownloadInitiatedVideosInformation` objects representing the video download entries.
     * @param videoAttributes - The attributes of the video to match against the entries.
     * @returns The index of the failed video entry in the `entries` array, or -1 if no matching entry is found.
     */
    getFailedVideoIndex(entries: DownloadInitiatedVideosInformation[], videoAttributes: videoAttributes): number {
        return entries.findIndex(
            (entry) =>
              (entry.downloadState === DOWNLOAD_STATE.MEDIA_ERROR ||
              entry.downloadState === DOWNLOAD_STATE.SERVICE_ERROR) && this.isObjectsEqual(entry.videoAttributes, videoAttributes)
        );
    }
     /* Checks if the download state indicates that the download has finished.
     * A download is considered finished if it completed successfully or failed with an error.
     * 
     * @param downloadState - The download state to check
     * @returns boolean - True if the download has finished (completed, media error, or service error)
     */
    isDownloadFinished(downloadState: DOWNLOAD_STATE): boolean {
        return downloadState === DOWNLOAD_STATE.COMPLETED || 
               downloadState === DOWNLOAD_STATE.MEDIA_ERROR || 
               downloadState === DOWNLOAD_STATE.SERVICE_ERROR ||
               downloadState === DOWNLOAD_STATE.NETWORK_ERROR ||
               downloadState === DOWNLOAD_STATE.FILE_MERGE_ERROR;
    }
    
    /**
     * Filters videos based on the current hostname according to business rules:
     * - On YouTube/Vimeo: Show all videos
     * - On other sites: Show only videos with downloadState === STARTED (in progress)
     * 
     * @param videos - Array of video objects to filter
     * @param hostname - The current hostname to check against
     * @returns Filtered array of videos based on hostname rules
     */
    filterVideosForHostname(videos: any[], hostname: string): any[] {
        const isYouTubeOrVimeo = this.isVideoDownloadSupportedHostname(hostname);
        if (isYouTubeOrVimeo) {
            // For YouTube/Vimeo, show all videos
            return videos;
        }
        // For other sites, show only videos that are in progress (downloadState === STARTED)
        return videos.filter(video =>
            video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.STARTED
        );
    }

}

const helperUtils = new HelperUtils();
export default helperUtils;
export { HelperUtils };