import { AUDIO_FORMAT, AudioFormat, AudioSpecificInfo, ContentLengthUnit, DownloadTriggeredPayload, MEDIA_CONTAINER_FORMAT, Segment, VIDEO_FORMAT, VideoFormat, VideoMediaInfo, VideoSpecificInfo } from "../interfaces";
import helperUtils from "../utils/HelperUtils";
import { VIDEO_SPECIFIC_INFO, INDEX_SEGMENT_URL, INIT_SEGMENT_BASE64 } from "../constants";
import { VideoAttributesManager } from "../VideoAttributesManager";

export class VideoMediaInfoManager {
    private static getSegmentUrls(format: AudioFormat | VideoFormat): string[] {
        if(format.segments) {
            return format.segments;
        }
        return [format.url];
    }

    private static getSegmentsData(format: AudioFormat | VideoFormat) {
        const data = {};
        if (format.indexSegmentUrl) {
            data[INDEX_SEGMENT_URL] = format.indexSegmentUrl;
        }
        if (format.initSegmentBase64) {
            data[INIT_SEGMENT_BASE64] = format.initSegmentBase64;
        }
        return data;
    }

    private static formatVideoData(videoFormat: VideoFormat): VideoSpecificInfo {
        let data: VideoSpecificInfo = {
            videoFormat: videoFormat.codecs as unknown as VIDEO_FORMAT,
            videoResolution: videoFormat.height,
            videoSegmentURLs: this.getSegmentUrls(videoFormat),
            contentLengthInKbOrMbOrGb: videoFormat.contentLengthInKbOrMbOrGb,
            contentLengthUnit: videoFormat.contentLengthUnit as any as ContentLengthUnit
        }
        data = {
            ...data,
            ...this.getSegmentsData(videoFormat)
        };
        return data;
    }

    private static formatAudioData(audioFormat: AudioFormat): AudioSpecificInfo {
        let data: AudioSpecificInfo = {
            audioFormat: audioFormat.codecs as unknown as AUDIO_FORMAT,
            audioSegmentURLs: this.getSegmentUrls(audioFormat),
            audioBitrate: audioFormat.audioBitrate,
            contentLengthInKbOrMbOrGb: audioFormat.contentLengthInKbOrMbOrGb,
            contentLengthUnit: audioFormat.contentLengthUnit as any as ContentLengthUnit
        }
        data = {
            ...data,
            ...this.getSegmentsData(audioFormat)
        }
        return data;
    }
    static formatData(mediaData: DownloadTriggeredPayload): VideoMediaInfo {
        const data: VideoMediaInfo = {
            videoId: mediaData.videoDetails.videoId,
            guid: helperUtils.createNewGuid(),
            title: mediaData.videoDetails.title,
            mediaContainerFormat: mediaData.videoFormat ? (mediaData.videoFormat.container as unknown as MEDIA_CONTAINER_FORMAT) : (mediaData.audioFormat.container as unknown as MEDIA_CONTAINER_FORMAT),
            isAudioOnly: mediaData.videoFormat ? false : true,
            audioSpecificInfo: this.formatAudioData(mediaData.audioFormat),
            videoAttributes: VideoAttributesManager.getVideoAttributes(mediaData)
        } 
        if (mediaData.videoFormat) {
            data[VIDEO_SPECIFIC_INFO] = this.formatVideoData(mediaData.videoFormat);
        }
        return data;
    }
}