
import { VideoProviders, IParsingRules, AdvancedSignaturePatterns, CDNConfigRules, VideoProvider, SupportedFormat, SpecialTelemetryConfig, SpecialTelemetryType, MetadataFetchIntervals } from '../interfaces';
import { CONSTANTS, CDN_CONFIG } from '../constants';
import { cdnFileDownloader } from '@avast/cdn-file-downloader-sdk';
import localRulesConfig from '../../data/videoDownloaderRules.json';


type ConfigsDownloadCallback = (config: CDNConfigRules) => void;

class CDNConfigManager {
    private maxConcurrentDownloads: number;
    private metadataFetchDelay: number;
    private metadataTTLInMs: number;
    private videoProviders: VideoProviders;
    private config: CDNConfigRules | null = null;
    private onConfigDownload: ConfigsDownloadCallback | null = null;
    private lastFetched: number | null = null;
    private fetchPromise: Promise<CDNConfigRules | null> | null = null;
    private alarmHandlerBound: (alarm: chrome.alarms.Alarm) => void;

    constructor() {
        this.maxConcurrentDownloads = 1;
        this.metadataFetchDelay = CONSTANTS.DEFAULT_FETCH_METADATA_IN_MILLISECONDS;
        this.metadataTTLInMs = CONSTANTS.DEFAULT_METADATA_TTL;
        this.videoProviders = {};
        this.alarmHandlerBound = this.handleAlarm.bind(this);
        // Always register alarm handler for service worker restart safety
        if (chrome && chrome.alarms && chrome.alarms.onAlarm) {
            chrome.alarms.onAlarm.addListener(this.alarmHandlerBound);
        }
    }

    /**
     * Sets the periodic alarm for config refresh.
     */
    private setConfigRefreshAlarm() {
        if (chrome && chrome.alarms && chrome.alarms.create && chrome.alarms.get) {
            chrome.alarms.get(CDN_CONFIG.VIDEO_DOWNLOADER_RULES_ALARM, (alarm) => {
                const expectedTimePeriod = CDN_CONFIG.VIDEO_DOWNLOADER_RULES_FETCH_INTERVAL_MINUTES;
                // If alarm does not exist, or exists but with a different period, create/update it
                if (!alarm || (alarm.periodInMinutes !== expectedTimePeriod)) {
                    chrome.alarms.create(CDN_CONFIG.VIDEO_DOWNLOADER_RULES_ALARM, {
                        periodInMinutes: expectedTimePeriod
                    });
                }
            });
        }
    }

    /**
     * Handles the alarm event for config refresh.
     */
    private handleAlarm(alarm: chrome.alarms.Alarm) {
        if (alarm && alarm.name === CDN_CONFIG.VIDEO_DOWNLOADER_RULES_ALARM) {
            this.fetchAndStoreConfig(true).catch((err) => {
                console.error('CDNConfigManager: Error refreshing config on alarm', err);
            });
        }
    }

    /**
      * Initializes the CDNConfigManager by setting the callback function
      * to be executed upon successful JSON download.
      */
    initialize(onConfigDownload?: ConfigsDownloadCallback): void {
        if (onConfigDownload) {
            this.onConfigDownload = onConfigDownload;
        }
    }

    /**
     * Fetches the configuration JSON file from a CDN and stores it in local storage.
     * Utilizes the cdnFileDownloader to retrieve the payload using specified URL, 
     * root certificate, and certificate information.
     */
    async fetchAndStoreConfig(force = false): Promise<CDNConfigRules | null> {
        // Prevent duplicate fetches
        if (this.fetchPromise) {
            return this.fetchPromise;
        }
        this.fetchPromise = (async () => {
            try {
                // Check last fetched time
                const { [CDN_CONFIG.CONFIGS_JSON_STORAGE_KEY]: cachedConfig, [CDN_CONFIG.CONFIG_LAST_FETCHED_KEY]: lastFetched } = await this.getConfigWithTimestamp();
                const now = Date.now();
                if (!force && cachedConfig && lastFetched && (now - lastFetched < CDN_CONFIG.CONFIG_FETCH_INTERVAL_MS)) {
                    this.config = cachedConfig;
                    this.lastFetched = lastFetched;
                    this.fetchPromise = null;
                    // Always ensure alarm is set for periodic refresh
                    this.setConfigRefreshAlarm();
                    return cachedConfig;
                }
                // Fetch from CDN
                const payload: CDNConfigRules = await cdnFileDownloader.getPayloadFromCdnFile(
                    CDN_CONFIG.CONFIG_JSON_DOWNLOAD_URL,
                    CDN_CONFIG.ROOT_CA,
                    CDN_CONFIG.CERT_INFO
                ) as unknown as CDNConfigRules;
                // If no cached config exists, use payload directly (first-time users)
                if (!cachedConfig) {
                    const reason = payload.configVersionId 
                        ? `No cached config found, using new config with version ${payload.configVersionId}`
                        : 'No cached config available, using payload config despite missing configVersionId';
                    console.log(`CDNConfigManager: ${reason}`);
                    await this.setConfigState(payload, now, true, true);
                    if (this.onConfigDownload) {
                        await this.onConfigDownload(payload);
                    }
                    return payload;
                }
                
                // Validate that fetched config has configVersionId
                if (!payload.configVersionId) {
                    console.warn('CDNConfigManager: Fetched config missing configVersionId, discarding and using cached/fallback config');
                    return this.useFallbackConfig(cachedConfig, lastFetched);
                }
                
                // Compare configVersionId with cached config
                const cachedConfigVersionId = cachedConfig?.configVersionId;
                if (cachedConfigVersionId && cachedConfigVersionId === payload.configVersionId) {
                    // Same version, no update needed
                    console.log(`CDNConfigManager: Config version unchanged (${payload.configVersionId}), skipping update`);
                    // Update last fetched time even if version is same (to prevent unnecessary re-fetches)
                    return this.setConfigState(cachedConfig, now, true);
                }
                
                // Version changed or cached config doesn't have configVersionId (backwards compatibility)
                if (cachedConfigVersionId) {
                    console.log(`CDNConfigManager: Config version changed from ${cachedConfigVersionId} to ${payload.configVersionId}, updating config`);
                } else {
                    console.log(`CDNConfigManager: Migrating from config without versionId to version ${payload.configVersionId}`);
                }
                
                await this.setConfigState(payload, now, true, true);
                if (this.onConfigDownload) {
                    await this.onConfigDownload(payload);
                }
                return payload;
            } catch (error: any) {
                // Fallback: try to use cached config if available, otherwise use local bundled config
                const { [CDN_CONFIG.CONFIGS_JSON_STORAGE_KEY]: cachedConfig } = await this.getConfigWithTimestamp();
                return this.useFallbackConfig(cachedConfig, null);
            }
        })();
        return this.fetchPromise;
    }

    /**
     * Helper to get config and last fetched timestamp from storage
     */
    private getConfigWithTimestamp(): Promise<{ [key: string]: any }> {
        return new Promise((resolve) => {
            chrome.storage.local.get([
                CDN_CONFIG.CONFIGS_JSON_STORAGE_KEY,
                CDN_CONFIG.CONFIG_LAST_FETCHED_KEY
            ], (result) => {
                resolve(result);
            });
        });
    }

    /**
     * Helper method to set config state (config, lastFetched, storage, alarm, fetchPromise).
     * Used when updating to a cached config or same-version config.
     * 
     * @param config - The config to set
     * @param lastFetched - The timestamp when config was last fetched
     * @param updateStorage - Whether to update storage with last fetched timestamp only (default: true)
     * @param storeConfig - Whether to also store the config itself in storage (default: false)
     * @returns The config that was set
     */
    private async setConfigState(config: CDNConfigRules, lastFetched: number, updateStorage: boolean = true, storeConfig: boolean = false): Promise<CDNConfigRules> {
        this.config = config;
        this.lastFetched = lastFetched;
        
        const storageData: { [key: string]: any } = {};
        if (updateStorage) {
            storageData[CDN_CONFIG.CONFIG_LAST_FETCHED_KEY] = lastFetched;
        }
        if (storeConfig) {
            storageData[CDN_CONFIG.CONFIGS_JSON_STORAGE_KEY] = config;
        }
        
        if (Object.keys(storageData).length > 0) {
            await chrome.storage.local.set(storageData);
        }
        
        this.setConfigRefreshAlarm();
        this.fetchPromise = null;
        return config;
    }


    /**
     * Helper method to use fallback config (cached or local) when CDN fetch fails or config is invalid.
     * Sets all necessary state and handles callbacks.
     * 
     * @param cachedConfig - The cached config from storage, if available
     * @param lastFetched - The timestamp when config was last fetched, if available
     * @returns The fallback config (cached or local)
     */
    private async useFallbackConfig(cachedConfig: CDNConfigRules | undefined, lastFetched: number | null): Promise<CDNConfigRules> {
        const now = Date.now();
        if (cachedConfig) {
            return this.setConfigState(cachedConfig, lastFetched || now, true);
        }

        // Fallback to local bundled config
        const localRulesConfigData = this.getLocalConfig();
        this.config = localRulesConfigData;
        this.setConfigRefreshAlarm();
        if (this.onConfigDownload) {
            await this.onConfigDownload(localRulesConfigData);
        }
        this.fetchPromise = null;
        return localRulesConfigData;
    }

    /**
     * Gets the local bundled configuration as a fallback.
     * @returns The local CDNConfigRules configuration
     */
    private getLocalConfig(): CDNConfigRules {
        return localRulesConfig as unknown as CDNConfigRules;
    }

    /**
     * Get config from memory, or from storage if not loaded. Waits for fetch if in progress.
     */
    async getConfig(): Promise<CDNConfigRules | null> {
        if (this.fetchPromise) {
            return this.fetchPromise;
        }
        if (this.config) {
            return this.config;
        }
        // Try to get from storage
        const { [CDN_CONFIG.CONFIGS_JSON_STORAGE_KEY]: cachedConfig } = await this.getConfigWithTimestamp();
        if (cachedConfig) {
            this.config = cachedConfig;
            return cachedConfig;
        }
        // If not in storage, fetch from CDN (fallback)
        return this.fetchAndStoreConfig();
    }

    /**
     * Gets the maximum number of concurrent downloads allowed.
     * @returns The maximum number of concurrent downloads.
     */
    async getMaxConcurrentDownloads(): Promise<number> {
        const config = await this.getConfig();
        return config?.queueConfig?.maxConcurrentDownloads || CONSTANTS.DEFAULT_MAX_CONCURRENT_DOWNLOADS;
    }

    /**
     * Gets the list of video providers.
     * @returns An object containing video providers mapped by their names.
     */
    async getVideoProviders(): Promise<VideoProviders | undefined> {
        const config = await this.getConfig();
        return config.videoProviders;
    }

    /**
     * Retrieves the video provider configuration for the specified provider name.
     *
     * @param providerName - The name of the video provider to retrieve.
     * @returns A promise that resolves to the `VideoProvider` object corresponding to the given provider name.
     * @throws An error if the specified provider is not found in the configuration.
     */
    private async getProvider(providerName: string): Promise<VideoProvider> {
        const providersArr: VideoProviders = await this.getVideoProviders()
        const provider: VideoProvider = providersArr[providerName];
        if (!provider) {
            throw new Error(`CDNConfigManager: Provider '${providerName}' not found in config.`);
        }
        return provider;
    }

    /**
     * Retrieves the parsing rules for a specific video provider.
     * @param providerName - The name of the video provider.
     * @returns The parsing rules for the specified video provider.
     * @throws An error if the video provider is not found.
     */

    async getParsingRules(providerName: string): Promise<IParsingRules | undefined> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.videoParsingRules;
        } catch(error) {
            return null;
        } 
    }

    /**
     * Retrieves the metadata URL for a given provider.
     *
     * @param providerName - The name of the provider whose metadata URL is to be fetched.
     * @returns A promise that resolves to the metadata URL as a string, or `null` if an error occurs.
     * @throws Will return `null` if the provider cannot be retrieved or an error occurs during the process.
     */
    async getMetadataUrl(providerName: string): Promise<string> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.metadataURL;
        } catch(error) {
            return null;
        } 
    }

    /**
     * Retrieves the supported formats for a given provider.
     *
     * @param providerName - The name of the provider whose supported formats are to be fetched.
     * @returns A promise that resolves to the supported formats of the provider, or `null` if an error occurs.
     * @throws Will not throw an error; instead, returns `null` in case of failure.
     */
    async getSupportedFormats(providerName: string): Promise<SupportedFormat> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.supportedFormats;
        } catch(error) {
            return null;
        } 
    }

    /**
     * Retrieves a specific property value from the video provider's data.
     *
     * @param providerName - The name of the video provider to retrieve data for.
     * @param property - The specific property to retrieve from the provider's data.
     * @returns A promise that resolves to the value of the specified property, or `null` if an error occurs.
     * @throws Will log an error to the console if the provider cannot be retrieved or the property is invalid.
     */
    async getVideoProviderMetaData(providerName: string, property: string): Promise<any> {
        try {
            const provider: VideoProvider = await this.getProvider(providerName);
            return provider['metaDataParsingRules'][property];
        } catch(error) {
            console.error(error);
            return null;
        }
    }

    /**
     * Retrieves the advanced signature patterns for a specific video provider.
     * @param providerName - The name of the video provider.
     * @returns The advanced signature patterns for the specified video provider, or undefined if not available.
     * @throws An error if the video provider is not found.
     */

    async getAdvancedSignaturePatterns(providerName: string): Promise<AdvancedSignaturePatterns | undefined> {
        const config = await this.getConfig();
        const provider = config.videoProviders[providerName];
        if (!provider) {
            throw new Error(`CDNConfigManager: Provider '${providerName}' not found in config.`);
        }
        return provider.advancedSignaturePatterns;
    }

    /**
     * Retrieves the interval for special telemetry in milliseconds.
     * 
     * @returns {Promise<number>} A promise that resolves to the interval in milliseconds.
     * @throws {Error} If the configuration or special telemetry configuration is not available.
     */
    async getSpecialTelemetryConfigs(): Promise<SpecialTelemetryConfig> {
        const config = await this.getConfig();
        const specialTelemetryConfig: SpecialTelemetryConfig = config.specialTelemetryConfigs;
        return specialTelemetryConfig;
    }

    /**
     * Retrieves the metadata fetch intervals for a given provider.
     *
     * @param provider - The name of the provider for which metadata fetch intervals are requested.
     * @returns A promise that resolves to an object containing:
     *   - `metadataTTL`: The time-to-live (TTL) for metadata in milliseconds.
     *   - `killSwitchIntervalInMs`: The interval for the kill switch in milliseconds.
     * @throws Will throw an error if the provider details cannot be retrieved.
     */
    async getMetadataFetchIntervals(provider: string): Promise<MetadataFetchIntervals> {
        const providerdetails = await this.getProvider(provider);
        return { metadataTTLInMs: providerdetails.metadataTTLInMs, killSwitchIntervalInMs: providerdetails.killSwitchIntervalInMs };
    }

    /**
     * Retrieves the acceptable error count from the configuration.
     *
     * @returns {Promise<number>} A promise that resolves to the acceptable error count.
     * @throws {Error} If there is an issue retrieving the configuration.
     */
    async getAcceptableErrorCount(): Promise<number> {
        const config = await this.getConfig();
        return config.acceptableErrorCount;
    }

    /**
     * Retrieves the chunk size in bytes for segmented downloads for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the chunk size in bytes.
     */
    async getChunkSizeInBytes(providerName: string, defaultValue: number): Promise<number> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.chunkSizeInBytes || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the maximum number of chunks for segmented downloads for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the maximum number of chunks.
     */
    async getChunkSizeInCount(providerName: string, defaultValue: number): Promise<number> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.chunkSizeInCount || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the default mime type for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the default mime type.
     */
    async getDefaultMimeType(providerName: string, defaultValue: string): Promise<string> {
        try {
            const provider = await this.getProvider(providerName);
            // Get the first supported format as default
            const defaultFormat = provider.supportedFormats?.video?.[0] || provider.supportedFormats?.audio?.[0];
            return defaultFormat?.mimetype || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the maximum supported content length for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the maximum supported content length in bytes.
     */
    async getMaxSupportedContentLength(providerName: string, defaultValue: number): Promise<number> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.maxSupportedContentLength || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the maximum segmentable content length for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the maximum segmentable content length in bytes.
     */
    async getMaxSegmentableContentLength(providerName: string, defaultValue: number): Promise<number> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.maxSegmentableContentLength || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the maximum supported video duration for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default value to return if not configured.
     * @returns A promise that resolves to the maximum supported video duration in milliseconds.
     */
    async getMaxSupportedVideoDurationInMs(providerName: string, defaultValue: number): Promise<number> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.maxSupportedVideoDurationInMs || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

    /**
     * Retrieves the bot detection configuration for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @returns A promise that resolves to the bot detection configuration, or null if not configured.
     */
    async getBotDetectionConfig(providerName: string): Promise<{botConditions: Array<{status: string, reason: string}>} | null> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.botDetectionConfig || null;
        } catch (error) {
            return null;
        }
    }

    /**
     * Retrieves the player ID for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @returns A promise that resolves to the player ID string, or null if not configured.
     */
    async getPlayerId(providerName: string): Promise<string | null> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.advancedSignaturePatterns?.PLAYER_ID || null;
        } catch (error) {
            return null;
        }
    }

    /**
     * Retrieves the BotGuard request key for a specific video provider.
     * Returns the CDN value if available, otherwise returns the default.
     * 
     * @param providerName - The name of the video provider
     * @param defaultKey - The default key to use if not found in CDN
     * @returns The BotGuard request key
     */
    async getBotGuardRequestKey(providerName: string, defaultKey: string): Promise<string> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.botGuardRequestKey || defaultKey;
        } catch (error) {
            return defaultKey;
        }
    }

    /**
     * Retrieves the client identifier for a specific video provider.
     *
     * @param providerName - The name of the video provider.
     * @param defaultValue - The default client value to return if not configured.
     * @returns A promise that resolves to the client identifier string.
     */
    async getClient(providerName: string, defaultValue: string): Promise<string> {
        try {
            const provider = await this.getProvider(providerName);
            return provider.advancedSignaturePatterns?.CLIENT || defaultValue;
        } catch (error) {
            return defaultValue;
        }
    }

}
const cdnConfigManager = new CDNConfigManager();
export default cdnConfigManager;

