import { DownloadTriggeredPayload, videoAttributes, VideoMetaData } from "./interfaces";

class VideoAttributesManager {
  /**
     * Retrieves video attributes based on the provided format.
     *
     * @param format - The payload containing video and audio format details.
     * @returns An object containing either the video resolution or the audio bitrate,
     *          depending on the presence of the video format in the payload.
     */
  static getVideoAttributes(format: DownloadTriggeredPayload): videoAttributes {
    if (format.videoFormat) {
        return {
            resolution: format.videoFormat.height
        }
    }
    return {
        audioBitrate: format.audioFormat.audioBitrate,
    };
 }

/**
 * Retrieves the appropriate video and audio formats based on the provided video attributes
 * and metadata. If a resolution is specified in the video attributes, it attempts to find
 * a matching video format with the specified resolution. Otherwise, it selects an audio
 * format based on the specified audio bitrate.
 *
 * @param videoAttributes - The attributes of the video, including resolution and audio bitrate.
 * @param metaData - The metadata of the video, including available formats and video details.
 * @returns An object containing the selected video format (if applicable), audio format, 
 *          and video details.
 */
 static getFormatFromAttributes(videoAttributes: videoAttributes, metaData: VideoMetaData): DownloadTriggeredPayload {
    if (videoAttributes.resolution) {
        const videoFormat = metaData.formats.videoFormats.find(item => item.height === videoAttributes.resolution);
        const audioFormat = metaData.formats.audioFormats[0];
        return {
            videoFormat,
            audioFormat,
            videoDetails: metaData.videoDetails
        }
    }
    return {
        audioFormat: metaData.formats.audioFormats.find(item => item.audioBitrate === videoAttributes.audioBitrate),
        videoDetails: metaData.videoDetails
    }
 }
}
export { VideoAttributesManager };