import { ThemeChangeDetails, THEMES } from "../interfaces";
import { videoDownloaderStoreService } from "../store/services/VideoDownloaderStoreService";
import helperUtils from "../utils/HelperUtils";

class ThemeManager {

    initialize() {
        try {
            (chrome as any).avast.themes.onThemeChanged.addListener(this.onThemeChange.bind(this));
        } catch (error) {
            console.error("Error initializing theme manager:", error);
        }
    }

    /**
     * Handles the theme change event and updates the application's theme accordingly.
     *
     * @param themeChangeDetails - An object containing details about the theme change.
     * @param themeChangeDetails.isDark - A boolean indicating whether the dark theme is enabled.
     */
    onThemeChange(themeChangeDetails: THEMES) {
        videoDownloaderStoreService.setTheme({
            updatedTheme: themeChangeDetails
        });
    }

    /**
     * Handles the retrieval of the dark mode setting and sends the result as a response.
     *
     * @param sendResponse - A callback function to send the retrieved dark mode setting.
     *                        The function takes a single parameter `response` which contains
     *                        the value indicating whether dark mode is set.
     * @returns A promise that resolves once the dark mode setting is retrieved and the response is sent.
     */
    async handleIsDarkModeSet(sendResponse: (response: any) => void) {
        const isDarkModeSet = await helperUtils.isBrowserDarkThemeEnabled();
        sendResponse(isDarkModeSet);
    }
}
const themeManager = new ThemeManager();
export {
     themeManager
};
