import { CONSTANTS, DATE_OF_INSTALL_LOCAL_STORAGE_KEY, MESSAGE_TYPES, OFFSCREEN_MESSAGE_TYPES, REDUX_ACTIONS, TabStatus, VIDEO_PROVIDER, VIDEO_PROVIDER_INFO, VIDEO_PROVIDERS_REQUIRE_URL_CHANGE_LISTENER, VIDEO_DOWNLOAD_METRICS_KEY } from '../constants';
import { VideoInfo, VideoMetaData, CDNConfigRules, MediaMetaDataExtractor, DOWNLOAD_STATE, videoAttributes } from '../interfaces';
import cdnConfigManager from './CDNConfigManager';
import youtubeMetaDataExtractor from '../YoutubeMetaDataExtractor';
import vimeoMetaDataExtractor from '../VimeoMetaDataExtractor';
import { videoDownloaderStoreService } from '../store/services/VideoDownloaderStoreService';
import queueControllerBG from './QueueControllerBG';
import helperUtils from '../utils/HelperUtils';
import iconBadgeManager from './IconBadgeManager';
import { telemetryManager } from '../telemetry/telemetryManager';
import { heartbeatHelper } from '../telemetry/heartbeatHelper';
import { EULA_ACTION, EULA_VALUE, TELEMETRY_EVENT_TYPES, TELEMETRY_ORIGIN } from '../telemetry/telemetryConstants';
import { sessionStore, localStore } from '../utils/storageManager';
import { themeManager } from '../theme/ThemeManager';
import { StorageUtils } from '../utils/storageUtils';

class VideoDownloaderBG {
    private metaDataExtractors: Map<string, MediaMetaDataExtractor>;
    constructor() {
        /**
         * Initializes the `VideoDownloaderBG`
         */
        themeManager.initialize();
        telemetryManager.init();
        heartbeatHelper.init(CONSTANTS.HEARTBEAT_INTERVAL_IN_MILLISECONDS);
        this.addTabListeners();
        this.handleMessages = this.handleMessages.bind(this);
        this.metaDataExtractors = new Map<VIDEO_PROVIDER, MediaMetaDataExtractor>([
            [VIDEO_PROVIDER.YOUTUBE, youtubeMetaDataExtractor],
            [VIDEO_PROVIDER.VIMEO, vimeoMetaDataExtractor]
        ]);

    }

    /**
     * Handles incoming messages from other parts of the extension.
     * 
     * @param message - The message object containing the type and data of the request.
     * @param sender - The sender of the message, provided by the Chrome runtime.
     * @param sendResponse - A callback function to send a response back to the sender.
     * @returns A promise that resolves when the message is processed.
     */
    handleMessages(message: any, sender: chrome.runtime.MessageSender, sendResponse: (response: any) => void): any {
        try {
            if (message.type === MESSAGE_TYPES.FETCH_METADATA) {
                const {providerName, videoId} = message.payload;
                queueControllerBG.enqueueVideoMetadata(providerName, videoId,sendResponse);
                // Return true to indicate async response
                return true;
            } else if (message.type === OFFSCREEN_MESSAGE_TYPES.DOWNLOAD_TRIGGERED) {
                queueControllerBG.enqueueVideosForDownload(message.videoInfoList)
                    .then(success => {
                        if (success) {
                            sendResponse({ success: true, message: 'Download started' });
                        } else {
                            sendResponse({ success: false, message: 'Failed to enqueue videos' });
                        }
                    });
            } else if (message.type === MESSAGE_TYPES.GET_PARSING_RULES) {
                const config = cdnConfigManager.getConfig().then((config) => {
                    sendResponse({success: true, config })
                })
            }
            else if (message.type === OFFSCREEN_MESSAGE_TYPES.DOWNLOAD_COMPLETION_STATUS) {
                const videoId = message.payload?.videoId;
                const downloadState = message.payload?.downloadCompletionStatus;
                const videoAttributes = message.payload.videoAttributes;
                
                // Update download state in Redux store first
                videoDownloaderStoreService.setDownloadState({
                    videoId,
                    downloadState: downloadState,
                    videoAttributes: videoAttributes
                });
                
                // Send telemetry for terminal download states after store is updated
                if (helperUtils.isDownloadFinished(downloadState)) {
                    // Handle telemetry asynchronously to avoid blocking the main flow
                    this.sendDownloadCompletedTelemetry(videoId, downloadState, videoAttributes);
                }
                
                queueControllerBG.dequeueVideoAfterDownload(videoId);
            }
            else if (message.type === MESSAGE_TYPES.SET_IFRAME_POPUP_HEIGHT) {
                // Relay popup height to the content script in the sender's tab
                if (sender.tab && sender.tab.id) {
                    chrome.tabs.sendMessage(sender.tab.id, {
                        type: MESSAGE_TYPES.SET_IFRAME_POPUP_HEIGHT,
                        height: message.height
                    });
                }
            }
            else if (message.type === OFFSCREEN_MESSAGE_TYPES.PROGRESS_UPDATED) {
                const { progressInformation } = message;
                const { videoId, progressPercentage } = progressInformation;
                videoDownloaderStoreService.setProgress({
                    videoId,
                    progressPercentage,
                });
            } else if(message.type === "GET_EXTENSION_VERSION") {
                sendResponse({ version: chrome.runtime.getManifest().version });
            } else if (message.type === MESSAGE_TYPES.SEND_TELEMETRY) {
                // Handle telemetry from UI components to avoid bundling telemetryManager in UI
                this.handleTelemetryMessage(message.payload);
            } else if (message.type === MESSAGE_TYPES.VIDEO_DOWNLOAD_STARTED) {
                videoDownloaderStoreService.triggerDownload({
                    ...message.payload
                });
            } else if(message.type === MESSAGE_TYPES.EULA_ACCEPTED) {
                videoDownloaderStoreService.setEulaAccepted();
                telemetryManager.sendEULAClickEvent(EULA_ACTION.EULA_CTA,EULA_VALUE.CHECKBOX_CHECKED);
            } else if(message.type === MESSAGE_TYPES.EULA_DISMISSED) {
                videoDownloaderStoreService.setEulaDismissed();
                telemetryManager.sendEULAClickEvent(EULA_ACTION.EULA_CLOSE);
            } else if(message.type === MESSAGE_TYPES.RETRY_CLICKED) {
                videoDownloaderStoreService.retryClicked({
                    ...message.payload
                });
                telemetryManager.sendRetryClickEvent();
            } else if (message.type === MESSAGE_TYPES.SHOW_IN_FOLDER_CLICKED) {
                telemetryManager.sendShowInFolderClickEvent();
            } else if (message.type === MESSAGE_TYPES.CANCEL_CLICKED) {
                videoDownloaderStoreService.cancelClicked({
                    ...message.payload
                })
            }
            // 'Show in folder' feature is not available due to browser limitations.
            // Chrome extensions cannot open a folder or highlight a file unless it was downloaded using the browser’s Downloads API.
            // If files are saved with custom methods (like ffmpeg or WASM), there is no way to open the folder or highlight the file programmatically.
        } catch (error: any) {
            return { success: false, error: error.message };
        }
        return true;
    }

    /**
     * Sends download outcome telemetry based on download completion status.
     * Retrieves the download source from Redux store and sends appropriate telemetry event.
     * 
     * @param videoId - The ID of the video that completed downloading
     * @param downloadState - The final state of the download (COMPLETED, MEDIA_ERROR, SERVICE_ERROR)
     * @param mediaAttributes - The media attributes to match the correct download entry
     * @returns Promise<void> - Resolves when telemetry is sent or fails gracefully
     */
    private async sendDownloadCompletedTelemetry(
        videoId: string, 
        downloadState: DOWNLOAD_STATE, 
        mediaAttributes: any
    ): Promise<void> {
            // Get current Redux store state
            const state = await videoDownloaderStoreService.getState();
            const downloadInitiatedVideos = state?.downloadInitiatedVideos?.downloadInitiatedVideos || {};
            
            // Find downloads for this specific video
            const filteredVideos = downloadInitiatedVideos[videoId] || [];
            
            // Find the exact download entry that matches our video attributes
            const filteredVideo = filteredVideos.find(entry => 
                helperUtils.isObjectsEqual(entry.videoAttributes, mediaAttributes)
            );
            const isSuccessful = downloadState === DOWNLOAD_STATE.COMPLETED;
            await telemetryManager.sendDownloadOutcomeEvent(filteredVideo.downloadSource, isSuccessful);

            // Heartbeat telemetry: update local storage counts
            if (isSuccessful) {
                // Increment downloaded_videos_count
                await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.DOWNLOADED_VIDEOS_COUNT);
            } else {
                // Increment failed_video_downloads_count
                await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.FAILED_VIDEO_DOWNLOADS_COUNT);
                // Fetch content length information from metadata
                const contentLengthInfo = this.getContentLengthInfoFromMetadata(state, videoId, filteredVideo.videoAttributes);
                await this.sendDownloadErrorTelemetry(videoId, downloadState, contentLengthInfo, filteredVideo?.downloadSource as TELEMETRY_ORIGIN, mediaAttributes);
            }
    }

    /**
     * Fetches content length information from metadata based on video attributes.
     * Since only one provider will exist for this context, we find the provider dynamically.
     * 
     * @param state - The Redux store state
     * @param videoId - The video ID
     * @param videoAttributes - The video attributes containing resolution or audio bitrate
     * @returns Object containing contentLengthInKbOrMbOrGb and contentLengthUnit, or null if not found
     */
    private getContentLengthInfoFromMetadata(state: any, videoId: string, videoAttributes: videoAttributes): any {
        try {
            const metadataValues = state?.metaData?.metadataValues || {};
            
            // Early return if metadataValues is empty or null
            if (!metadataValues || Object.keys(metadataValues).length === 0) {
                return null;
            }
            
            // Find the provider that has metadata for this videoId
            const providerNames = Object.keys(metadataValues);
            const provider = providerNames.find(providerName => 
                metadataValues[providerName] && metadataValues[providerName][videoId]
            );
            
            if (!provider) {
                return null;
            }
            
            const videoMetadata = metadataValues[provider][videoId];
            const formats = videoMetadata?.formats;
            
            if (!formats) {
                return null;
            }
            
            // Check if we have resolution (video format) or audio bitrate (audio format)
            if (videoAttributes?.resolution) {
                // Look in videoFormats
                const videoFormats = formats.videoFormats || [];
                const matchingVideoFormat = videoFormats.find((format: any) => 
                    format.height === videoAttributes.resolution
                );
                
                if (matchingVideoFormat) {
                    return {
                        contentLengthInKbOrMbOrGb: matchingVideoFormat.contentLengthInKbOrMbOrGb,
                        contentLengthUnit: matchingVideoFormat.contentLengthUnit,
                        provider: provider,
                        formatType: 'video'
                    };
                }
            } else if (videoAttributes?.audioBitrate) {
                // Look in audioFormats
                const audioFormats = formats.audioFormats || [];
                const matchingAudioFormat = audioFormats.find((format: any) => 
                    format.audioBitrate === videoAttributes.audioBitrate
                );
                
                if (matchingAudioFormat) {
                    return {
                        contentLengthInKbOrMbOrGb: matchingAudioFormat.contentLengthInKbOrMbOrGb,
                        contentLengthUnit: matchingAudioFormat.contentLengthUnit,
                        provider: provider,
                        formatType: 'audio'
                    };
                }
            }
            
            return null;
        } catch (error) {
            console.error('Error fetching content length from metadata:', error);
            return null;
        }
    }

    /**
     * Sends error telemetry for network errors with resolution or audio bitrate information.
     * 
     * @param videoId - The ID of the video that failed due to network error
     * @param videoAttributes - The video attributes containing resolution or audio bitrate
     */
    private async sendDownloadErrorTelemetry(videoId: string, downloadState: DOWNLOAD_STATE, contentLengthInfo: any, downloadSource: TELEMETRY_ORIGIN, videoAttributes: videoAttributes): Promise<void> {
        try {
            // Send error telemetry using telemetryManager
            await telemetryManager.sendDownloadErrorTelemetry(videoId, downloadState, contentLengthInfo, downloadSource, videoAttributes);
        } catch (error) {
            console.error('Failed to send download error telemetry:', error, ' for downloadState: ', downloadState);
        }
    }

    /**
     * Handles telemetry messages from UI components.
     * This prevents UI components from directly importing telemetryManager.
     * 
     * @param payload - The telemetry payload containing eventType, origin, and event data
     */
    private handleTelemetryMessage(payload: any): void {
            const { eventType } = payload;
            
            switch (eventType) {
                case TELEMETRY_EVENT_TYPES.RESOLUTION_SELECTION:
                    const { label, action, value } = payload;
                    telemetryManager.sendResolutionSelectionEvent(label, action, value);
                    break;
                case TELEMETRY_EVENT_TYPES.DOWNLOAD_CLICK:
                    const { origin: downloadOrigin } = payload;
                    telemetryManager.sendDownloadClickEvent(downloadOrigin as TELEMETRY_ORIGIN);
                    break;
                case TELEMETRY_EVENT_TYPES.CANCEL_CLICK:
                    const { origin: cancelOrigin } = payload;
                    telemetryManager.sendCancelClickEvent(cancelOrigin as TELEMETRY_ORIGIN);
                    break;
                case TELEMETRY_EVENT_TYPES.INFO_CLICK:
                    const { origin: infoOrigin } = payload;
                    telemetryManager.sendInfoClickEvent(infoOrigin as TELEMETRY_ORIGIN);
                    break;
                case TELEMETRY_EVENT_TYPES.MENU_CLICK:
                    const { origin: menuOrigin } = payload;
                    telemetryManager.sendMenuClickEvent(menuOrigin as TELEMETRY_ORIGIN);
                    break;
                case TELEMETRY_EVENT_TYPES.VIDEO_NOT_FOUND_PAGEVIEW:
                    telemetryManager.sendVideoNotFoundPageviewEvent();
                    break;
                case TELEMETRY_EVENT_TYPES.POPOVER_PAGEVIEW:
                    telemetryManager.sendPopoverPageviewEvent();
                    break;
                case TELEMETRY_EVENT_TYPES.EULA_POPUP_ACCEPTED:
                    telemetryManager.sendEULAClickEvent(EULA_ACTION.EULA_CTA,EULA_VALUE.CHECKBOX_CHECKED);
                    break;
                case TELEMETRY_EVENT_TYPES.EULA_POPUP_DISMISSED:
                    telemetryManager.sendEULAClickEvent(EULA_ACTION.EULA_CLOSE);
                default:
                    console.warn('[TELEMETRY] VideoDownloaderBG - Unknown telemetry event type:', eventType);
            }
    }

    /**
     * Retrieve metadata information 
     * This method will use the MediaMetaDataExtractor to getMetadataInfo
     * @param providerName - name of the provider
     * @param videoId - id of the video to be downloaded
     */
    async getMetaDataInfo(providerName: string, videoId: string): Promise<VideoMetaData> {
        // TODO: Check if the videoId has already been processed/cached to avoid duplicate API calls (TBD)
        return this.metaDataExtractors.get(providerName).getMetadataInfo(videoId);
    }

    /**
    * Initializes listeners for handling runtime messages.
    */
    initListeners(): void {
        chrome.runtime.onInstalled.addListener(async (details) => {
            // Handle install and update telemetry
            const reason = details.reason;
            try {
              switch (reason) {
                case TELEMETRY_EVENT_TYPES.INSTALL:
                  await this.handleInstall();
                  break;
                case TELEMETRY_EVENT_TYPES.UPDATE:
                  await telemetryManager.sendExtensionUpdate();
                  break;
              }
            } catch (error) {
              console.error('[VideoDownloaderBG] Error sending install/update telemetry:', error);
            }
          });
          
      chrome.runtime.onMessage.addListener(
        this.handleMessages
      );
      // Listen for tab URL changes and notify content script only for relevant hostnames
      chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
        if (!tab.url) return;
        try {
          const url = new URL(tab.url);
          const hostname = url.hostname;
          if (!helperUtils.isSupportedVideoProviderHostname(hostname)) {
            return;
          }
          this.handleTabUpdate(tabId, changeInfo, tab);
        } catch (e) {
          // Ignore invalid URLs
        }
      });
      chrome.action.onClicked.addListener(async (tab) => {
        if (!tab.id) {
             return;
        }
        this.sendToggleIframePopupMessage(tab.id);
        // Send telemetry for extension icon click
        await telemetryManager.sendExtensionIconClickEvent();
      });
      
      // Handle EULA popup message
      chrome.runtime.onMessage.addListener((msg, sender) => {
        if (msg && msg.type === MESSAGE_TYPES.SHOW_EULA_POPUP) {
            // Use sender.tab.id directly if available
            const tabId = sender.tab && sender.tab.id;
            if (tabId) {
                telemetryManager.sendShowEULAEvent();
                this.injectEulaPopupScript(tabId);
            } 
        }
      });
    }

    /**
     * Sends a message to the content script to toggle the iframe popup.
     * @param tabId - The ID of the tab to send the message to.
     */
    sendToggleIframePopupMessage(tabId: number) {
      chrome.tabs.sendMessage(tabId, { type: MESSAGE_TYPES.TOGGLE_IFRAME_POPUP });
    }

    /**
     * Handles tab updates and notifies content script for all tabs.
     * Sends two distinct messages: one for DOM complete, one for URL change.
     */
    async handleTabUpdate(tabId: number, changeInfo: chrome.tabs.TabChangeInfo, tab: chrome.tabs.Tab) {
        try {
            chrome.tabs.sendMessage(tabId, {
                type: MESSAGE_TYPES.TAB_URL_CHANGED,
                url: tab.url,
                reason: 'url_changed'
            });
        } catch (err) {
            console.error(`[VideoDownloaderBG] Error in handleTabUpdate for tab ${tabId}:`, err);
        }
    }

    /**
     * Ensures that an offscreen document is initialized.
     * If it doesn't exist, it creates one with the required configuration.
     */
    async initializeOffscreenDocument(): Promise<void> {
        const offscreenUrl = chrome.runtime.getURL('../views/offscreen.html');
        const existingOffscreenContexts = await new Promise<chrome.runtime.ExtensionContext[]>((resolve, reject) => {
            chrome.runtime.getContexts({
                contextTypes: ['OFFSCREEN_DOCUMENT' as chrome.runtime.ContextType],
                documentUrls: [offscreenUrl]
            }, (contexts) => {
                if (chrome.runtime.lastError) {
                    reject(chrome.runtime.lastError);
                } else {
                    resolve(contexts);
                }
            });
        });
        if (existingOffscreenContexts && existingOffscreenContexts.length > 0) {
            return;
        }
        await chrome.offscreen.createDocument({
            url: '../views/offscreen.html',
            reasons: ['BLOBS'],
            justification: 'Required for WASM runtime and DOM operations'
        });
    }

     /**
     * Handles install event callback of extension
     */
     async handleInstall(): Promise<void> {
        const currentDate = new Date();
        const installDate = helperUtils.formatDateToYYYYMMDD(currentDate);
        await chrome.storage.local.set({
            [DATE_OF_INSTALL_LOCAL_STORAGE_KEY]: installDate,
        });
        await telemetryManager.sendExtensionInstall();
    }

    async init() {
        this.initListeners(); // add telemetry install and update listeners as first step
        await this.initializeOffscreenDocument();
        // Now set up listeners - offscreen is guaranteed to be ready
        await cdnConfigManager.fetchAndStoreConfig();
        // Initialize YouTube metadata extractor (needs offscreen to be ready for PoTokens)
        await youtubeMetaDataExtractor.init();
        // Fetch maxConcurrentDownloads from CDN 
        const config = await cdnConfigManager.getConfig();
        await queueControllerBG.init(config?.queueConfig);
    }
    
    /**
     * Injects the EULA popup script into the specified tab
     */
    async injectEulaPopupScript(tabId: number, format?: any): Promise<void> {

            
            // Then inject the script directly
            await chrome.scripting.executeScript({
                target: { tabId },
                files: ["EulaPopupCS.js"],
                world: "ISOLATED"
            });
    }

    /**
     * Updates the extension icon and badge based on the metadata count and availability.
     */
    async updateIconAndBadge() {
        const count = await videoDownloaderStoreService.getMetadataCount();
        if (count > 0) {
            chrome.action.setIcon({
                path: {
                    "16": "assets/images/extensionIconVideosAvailable_16.png",
                    "32": "assets/images/extensionIconVideosAvailable_32.png",
                    "48": "assets/images/extensionIconVideosAvailable_48.png",
                    "128": "assets/images/extensionIconVideosAvailable_128.png"
                }
            });
            chrome.action.setBadgeText({
                text: count > 999 ? '999+' : count.toString(),
            });
            chrome.action.setBadgeBackgroundColor({
                color: '#000000' // Black background for videos available
            });
            chrome.action.setBadgeTextColor({
                color: '#FFFF' // White text color
            });
        } else {
            chrome.action.setIcon({
                path: {
                    "16": "assets/images/extensionIconNovideosAvailable_16.png",
                    "32": "assets/images/extensionIconNovideosAvailable_32.png",
                    "48": "assets/images/extensionIconNovideosAvailable_48.png",
                    "128": "assets/images/extensionIconNovideosAvailable_128.png"
                }
            });
        }
    }

    /**
     * Updates the browser extension's icon to indicate that no videos are available.
     * 
     * This method sets the extension's action icon to a specific set of images
     * representing the "no videos available" state. It also clears any badge text
     * displayed on the extension's icon.
     * 
     * The icon paths are defined for multiple resolutions:
     * - 16x16
     * - 32x32
     * - 48x48
     * - 128x128
     * 
     * @returns {void}
     */
    private setNoVideosIcon() {
        chrome.action.setIcon({
            path: {
                "16": "assets/images/extensionIconNovideosAvailable_16.png",
                "32": "assets/images/extensionIconNovideosAvailable_32.png",
                "48": "assets/images/extensionIconNovideosAvailable_48.png",
                "128": "assets/images/extensionIconNovideosAvailable_128.png"
            }
        });
        chrome.action.setBadgeText({ text: "" });
    }

    /**
     * Handles the badge and icon updates for a specific browser tab based on its URL.
     * 
     * This method retrieves the URL of the given tab, determines if the hostname
     * supports video downloads, and updates the browser action icon and badge accordingly.
     * 
     * @param tabId - The ID of the browser tab for which the badge and icon need to be updated.
     * @returns A promise that resolves when the badge and icon updates are complete.
     */
    private async refreshBadgeForTabChanges(tabId: number) {
        try {
            const url: string = await helperUtils.getUrlFromTabId(tabId);
            if (!url) {
                this.setNoVideosIcon();
                return;
            }
            const hostname: string = new URL(url).hostname;
            if (helperUtils.isVideoDownloadSupportedHostname(hostname)) {
                await this.updateIconAndBadge();
            } else {
                this.setNoVideosIcon();
            }
        } catch(error) {
            console.log(error);
            this.setNoVideosIcon();
        }
    }

    /**
     * Adds listeners for Chrome tab events to handle badge updates.
     * 
     * This method sets up listeners for the following Chrome tab events:
     * - `onActivated`: Triggered when a tab is activated. The badge update is handled for the activated tab.
     * - `onUpdated`: Triggered when a tab is updated. If the update status is "completed", the badge update is handled for the updated tab.
     * 
     * The badge update logic is delegated to the `refreshBadgeForTabChanges` method.
     */
    addTabListeners() {
        chrome.tabs.onActivated.addListener(({tabId, windowId}) => iconBadgeManager.refreshBadgeForTabChanges(tabId));   
        chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
            if (changeInfo.status === TabStatus.COMPLETE) {
                iconBadgeManager.refreshBadgeForTabChanges(tabId);
            }
        });
        chrome.windows.onFocusChanged.addListener((windowId) => {
            if (windowId === chrome.windows.WINDOW_ID_NONE) {
                return;
            }
            chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
                if (tabs.length > 0) {
                    tabs.forEach(tab => {
                        iconBadgeManager.refreshBadgeForTabChanges(tab.id);
                    });
                }
            });
        });      
    }
}

const videoDownloaderBG = new VideoDownloaderBG();
videoDownloaderBG.init();
export default videoDownloaderBG;