import { videoDownloaderStoreService } from '../store/services/VideoDownloaderStoreService';
import helperUtils from '../utils/HelperUtils';

class IconBadgeManager {
    /**
     * Updates the extension icon and badge based on the metadata count and availability.
     */
    public async updateIconAndBadge() {
        const count = await videoDownloaderStoreService.getMetadataCount();
        if (count > 0) {
            chrome.action.setIcon({
                path: {
                    "16": "assets/images/extensionIconVideosAvailable_16.png",
                    "32": "assets/images/extensionIconVideosAvailable_32.png",
                    "48": "assets/images/extensionIconVideosAvailable_48.png",
                    "128": "assets/images/extensionIconVideosAvailable_128.png"
                }
            });
            chrome.action.setBadgeText({
                text: count > 999 ? '999+' : count.toString(),
            });
            chrome.action.setBadgeBackgroundColor({
                color: '#000000' // Black background for videos available
            });
            chrome.action.setBadgeTextColor({
                color: '#FFFF' // White text color
            });
        } else {
            chrome.action.setIcon({
                path: {
                    "16": "assets/images/extensionIconNovideosAvailable_16.png",
                    "32": "assets/images/extensionIconNovideosAvailable_32.png",
                    "48": "assets/images/extensionIconNovideosAvailable_48.png",
                    "128": "assets/images/extensionIconNovideosAvailable_128.png"
                }
            });
        }
    }

    /**
     * Updates the browser extension's icon to indicate that no videos are available.
     * 
     * This method sets the extension's action icon to a specific set of images
     * representing the "no videos available" state. It also clears any badge text
     * displayed on the extension's icon.
     * 
     * The icon paths are defined for multiple resolutions:
     * - 16x16
     * - 32x32
     * - 48x48
     * - 128x128
     * 
     * @returns {void}
     */
    private setNoVideosIcon() {
        chrome.action.setIcon({
            path: {
                "16": "assets/images/extensionIconNovideosAvailable_16.png",
                "32": "assets/images/extensionIconNovideosAvailable_32.png",
                "48": "assets/images/extensionIconNovideosAvailable_48.png",
                "128": "assets/images/extensionIconNovideosAvailable_128.png"
            }
        });
        chrome.action.setBadgeText({ text: "" });
    }

    /**
     * Handles the badge and icon updates for a specific browser tab based on its URL.
     * 
     * This method retrieves the URL of the given tab, determines if the hostname
     * supports video downloads, and updates the browser action icon and badge accordingly.
     * 
     * @param tabId - The ID of the browser tab for which the badge and icon need to be updated.
     * @returns A promise that resolves when the badge and icon updates are complete.
     */
    public async refreshBadgeForTabChanges(tabId: number) {
        try {
            const url: string = await helperUtils.getUrlFromTabId(tabId);
            if (!url) {
                this.setNoVideosIcon();
                return;
            }
            const hostname: string = new URL(url).hostname;
            if (helperUtils.isVideoDownloadSupportedHostname(hostname)) {
                await this.updateIconAndBadge();
            } else {
                this.setNoVideosIcon();
            }
        } catch(error) {
            console.log(error);
            this.setNoVideosIcon();
        }
    }
    
}

const iconBadgeManager = new IconBadgeManager();
export default iconBadgeManager;
