import { EULA_ACCEPTED_STATE_LOCAL_STORAGE_KEY, REDUX_ACTIONS } from '../../constants';
import { localStore } from '../../utils/storageManager';
import { EulaDetails } from '../../interfaces';

class EulaStore {

  static getDefaultState() {
    return {
      isEulaAccepted: false,
      eulaAcceptedTimestamp: null,
      eulaDismissed: false
    };
  }

  static async getInitialState(): Promise<EulaDetails> {
     const eulaAcceptanceDetails: EulaDetails = await localStore.getItem(EULA_ACCEPTED_STATE_LOCAL_STORAGE_KEY);
     return eulaAcceptanceDetails;
   }

  static eulaReducer(state = EulaStore.getDefaultState(), action: { type: string; payload: any }) {
    // TBD Need to update other states too , should be done in intengration
    switch (action.type) {
      case REDUX_ACTIONS.EULA_ACCEPTED:
        return {
          ...state,
          isEulaAccepted: true,
          eulaAcceptedTimestamp: Date.now(),
          eulaDismissed: true //should dismiss all the eula popups if download starts in one
        };
      case REDUX_ACTIONS.EULA_DISMISSED:
        return {
          ...state,
          eulaDismissed: true
        };
      case REDUX_ACTIONS.EULA_NOT_ACCEPT_DOWNLOAD_CLICK:
        return {
          ...state,
          eulaDismissed: false
        };
      default:
        return state;
    }
  };
}
export default EulaStore;
