import { MESSAGE_TYPES } from '../constants';
import { Platform, Types } from '@avast/youtube-downloader-lib';

/**
 * Handles execution of JavaScript code in the sandboxed iframe
 */
class SandboxExecutor {
    /**
     * Initializes the sandbox executor and configures Platform.shim.eval
     */
    public initialize(): void {
        Platform.shim.eval = async (data: Types.BuildScriptResult, env: Record<string, Types.VMPrimative>) => {
            // Build the return statement based on available env properties
            const returnProps = [];
            if (env.n) returnProps.push(`n: exportedVars.nFunction("${env.n}")`);
            if (env.sig) returnProps.push(`sig: exportedVars.sigFunction("${env.sig}")`);
            
            // Execute build script + return in sandbox (helper functions stay in scope)
            const fullCode = `${data.output}\nreturn { ${returnProps.join(', ')} };`;
            return await this.execute(fullCode, env);
        };
    }

    /**
     * Executes JavaScript code in the sandbox and returns the result
     * @param code - The JavaScript code to execute
     * @param env - Environment variables to provide as context
     * @returns Promise that resolves to the execution result
     */
    async execute(code: string, env: Record<string, any>): Promise<any> {
        return new Promise((resolve, reject) => {
            chrome.runtime.sendMessage({
                type: MESSAGE_TYPES.EXECUTE_SCRIPT,
                payload: { context: env, code }
            }, (response) => {
                if (chrome.runtime.lastError || response.payload.error) {
                    reject(new Error(response.payload.error || chrome.runtime.lastError.message));
                } else {
                    resolve(response.payload.result);
                }
            });
        });
    }
}

const sandboxExecutor = new SandboxExecutor();
export default sandboxExecutor;
