import { heartbeatManager, HeartbeatConfigs } from "@avast/heart-beat-sdk";
import { localStore } from "../utils/storageManager";
import { telemetryManager } from "./telemetryManager";
import { VIDEO_DOWNLOAD_METRICS_KEY } from "../constants";
import helperUtils from "../utils/HelperUtils";
import { HeartbeatDynamicTelemetryParams } from "../interfaces";
import { applicationSettingsManager } from "./applicationSettingsManager";

class HeartbeatHelper {

  /**
   * Helper function to get all video download metrics values from storage
   */
  private async getMetricsValuesFromStorage(): Promise<Record<string, number>> {
    const metricsValues: Record<string, number> = {};

    // Iterate over video download metrics keys and get values directly
    for (const [propertyName, storageKey] of Object.entries(VIDEO_DOWNLOAD_METRICS_KEY)) {
      metricsValues[propertyName] = await localStore.getItem<number>(storageKey) || 0;
    }

    return metricsValues;
  }

  /**
   * Helper function to create telemetry params object with computed properties
   * while maintaining type safety with the interface
   */
  private createTelemetryParams(
    metricsValues: Record<string, number>,
    currentTheme: string
  ): HeartbeatDynamicTelemetryParams {
    const params: Record<string, number | string> = {
      browser_theme: currentTheme,
      extension_theme: currentTheme
    };

    // Iterate over video download metrics keys and add them to params
    for (const [paramValue, paramName] of Object.entries(VIDEO_DOWNLOAD_METRICS_KEY)) {
      params[paramName] = metricsValues[paramValue];
    }
    
    // Type assertion is safe here because we know the computed properties
    // match the exact string literals expected by the interface
    return params as unknown as HeartbeatDynamicTelemetryParams;
  }

  /**
   * Function to get heartbeat params which will be called by heartbeat-sdk
   * while sending the hb ping and reset the heartbeat count returning params
   */
  private async getDynamicTelemetryParams(): Promise<HeartbeatDynamicTelemetryParams> {
    // Get all video download metrics values from storage
    const metricsValues = await this.getMetricsValuesFromStorage();
    const currentTheme = await helperUtils.getCurrentBrowserTheme();

    const dynamicTelemetryParams = this.createTelemetryParams(
      metricsValues,
      currentTheme
    );
    
    await this.resetVideoDownloadMetrics();

    return dynamicTelemetryParams;
  }

  /**
   * Reset all values in storage of download metrics after each heartbeat interval ping sent
   */
  private async resetVideoDownloadMetrics(): Promise<void> {
    // Iterate over all video download metrics keys and reset them to 0
    for (const storageKey of Object.values(VIDEO_DOWNLOAD_METRICS_KEY)) {
      await localStore.setItem(storageKey, 0);
    }
  }

  /**
   * Initializes the heartbeat manager with the required configuration.
   * This method sets up the heartbeat functionality using the telemetry manager's
   * super params and dynamic telemetry params.
   */
  async init(heartbeatInterval: number): Promise<void> {
    const applicationSettings = applicationSettingsManager.getApplicationSettings();
    const config: HeartbeatConfigs = {
      appName: chrome.runtime.getManifest().name,
      heartBeatIntervalInMilliSec: heartbeatInterval,
      superParams: await telemetryManager.getSuperParams(),
      getDynamicTelemetryParams: this.getDynamicTelemetryParams.bind(this),
      applicationSettings: applicationSettings,
      storageManager: localStore
    };
    await heartbeatManager.init(config);
  }
}

const heartbeatHelper = new HeartbeatHelper();
export { heartbeatHelper };

