import queueController from './QueueController';
import queueWorker from './QueueWorker';
import metadataQueueWorker from './MetadataQueueWorker';
import { QueueConfig, VideoMediaInfo } from '../interfaces';
import { CONSTANTS } from '../constants';

class QueueControllerBG {
    private maxConcurrentDownloads = CONSTANTS.DEFAULT_MAX_CONCURRENT_DOWNLOADS;
    private metadataFetchDelay = CONSTANTS.DEFAULT_FETCH_METADATA_IN_MILLISECONDS;

    async init(queueConfig: QueueConfig): Promise<void> {
        this.maxConcurrentDownloads = queueConfig?.maxConcurrentDownloads || CONSTANTS.DEFAULT_MAX_CONCURRENT_DOWNLOADS;
        this.metadataFetchDelay = queueConfig?.metadataFetchDelay || CONSTANTS.DEFAULT_FETCH_METADATA_IN_MILLISECONDS;
        await queueWorker.init(this.maxConcurrentDownloads);
        await metadataQueueWorker.init(this.metadataFetchDelay);
    }

    /**
     * Enqueue videos for download using the queueController
     */
    async enqueueVideosForDownload(videoMediaInfos: VideoMediaInfo[]): Promise<boolean> {
        return queueController.enqueueVideosForDownload(videoMediaInfos);
    }

    /**
     * Notify that a video download is complete using the queueController
     */
    dequeueVideoAfterDownload(videoId: string): void {
        queueController.dequeueVideoAfterDownload(videoId);
    }

    /**
     * Enqueue video metadata request for throttled processing
     */
    async enqueueVideoMetadata(providerName: string, videoId: string, sendResponse: (response: any) => void): Promise<void> {
        return queueController.enqueueVideoMetadata(providerName, videoId, sendResponse);
    }

    /**
     * Register a callback for new metadata requests
     */
    registerForMetadataRequest(callback: (providerName: string, videoId: string, sendResponse: (response: any) => void) => void): void {
        queueController.registerForMetadataRequest(callback);
    }
}

const queueControllerBG = new QueueControllerBG();
export default queueControllerBG;
