import { VideoMetaData, MediaMetaDataExtractor, METADATA_STREAMING_PROTOCOLS, VIDEO_COMPRESSION_STANDARDS, SupportedFormat, AudioFormat, VideoFormat, AudioFormatMetadata, VideoFormatMetadata} from './interfaces';
import cdnConfigManager from './background/CDNConfigManager';
import { VIDEO_PROVIDER_PROPERTY_MAP, VIDEO_PROVIDER } from './constants';
import { vimeoMediaFormatFilter } from './VimeoMediaFormatFilter';
import helperUtils from './utils/HelperUtils';
import { MetadataValidityUtils } from './utils/MetadataValidityUtils';

class VimeoMetaDataExtractor implements MediaMetaDataExtractor  {

    // determines whether live videos are present in this provider
    isLiveVideoApplicable = false;

    /**
     * Filters the supported streaming protocol from the provided array of streaming protocols.
     *
     * @param streamingProtocolArray - An array of streaming protocols to filter from.
     * @returns A promise that resolves to the first supported streaming protocol found in the input array.
     *
     * @throws Will throw an error if no supported streaming protocol is found.
     */
    private async filterSupportedStreamingProtocol(streamingProtocolArray: METADATA_STREAMING_PROTOCOLS[]): Promise<METADATA_STREAMING_PROTOCOLS> {
        const supportedStreamingProtocols = await cdnConfigManager.getVideoProviderMetaData(VIDEO_PROVIDER.VIMEO, VIDEO_PROVIDER_PROPERTY_MAP.supportedStreamingProtocols);
        const supportedProtocol: METADATA_STREAMING_PROTOCOLS = supportedStreamingProtocols.find(protocol => streamingProtocolArray.includes(protocol));
        return supportedProtocol;
    }

    /**
     * Filters the provided array of video compression standards and returns the first standard
     * that is supported by the Vimeo video provider.
     *
     * @param videoCompressionStandardsArray - An array of video compression standards to filter.
     * @returns A promise that resolves to the first supported video compression standard found in the input array.
     *          If no supported standard is found, the promise resolves to `undefined`.
     *
     * @throws This method relies on `cdnConfigManager.getVideoProviderData` to fetch supported standards,
     *         so any errors from that call will propagate.
     */
    private async filterSupportedVideoCompressionStandards(videoCompressionStandardsArray: VIDEO_COMPRESSION_STANDARDS[]): Promise<VIDEO_COMPRESSION_STANDARDS> {
        const supportedVideoCompressionStandards = await cdnConfigManager.getVideoProviderMetaData(VIDEO_PROVIDER.VIMEO, VIDEO_PROVIDER_PROPERTY_MAP.supportedVideoCompressionStandards);
        const supportedVideoCompressionStandard: VIDEO_COMPRESSION_STANDARDS = supportedVideoCompressionStandards.find(value => videoCompressionStandardsArray.includes(value));
        return supportedVideoCompressionStandard;
    }

    /**
     * Retrieves the URL of the video data that matches the supported video compression standard.
     *
     * @param videoSourceData - An object containing video source data, where keys represent
     *                          different video compression standards and their corresponding URLs.
     * @returns A promise that resolves to the URL of the video data matching the supported
     *          video compression standard.
     *
     * @throws Will throw an error if no supported video compression standard is found
     *         in the provided video source data.
     */
    private async getSupportedVideoDataUrl(videoSourceData: any) : Promise<string> {
        const supportedVideoCompressionStandardUrlPattern = await cdnConfigManager.getVideoProviderMetaData(VIDEO_PROVIDER.VIMEO, VIDEO_PROVIDER_PROPERTY_MAP.supportedVideoCompressionStandardUrlPattern);
        const videoCompressionStandardsArray = Object.keys(videoSourceData).filter((value: string) => value.includes(`${supportedVideoCompressionStandardUrlPattern}`)).map((val: string) => val.split(`${supportedVideoCompressionStandardUrlPattern}`)[0]);
        const supportedCompressiontechnique: VIDEO_COMPRESSION_STANDARDS = await this.filterSupportedVideoCompressionStandards(videoCompressionStandardsArray as unknown as VIDEO_COMPRESSION_STANDARDS[]);
        const supportedVideoDataUrl: string = videoSourceData[`${supportedCompressiontechnique}${supportedVideoCompressionStandardUrlPattern}`];
        return supportedVideoDataUrl;
    }

    /**
     * Constructs the final URL for media segments by resolving the base URL, relative path, 
     * and media path into a complete URL.
     *
     * @param baseURL - The base URL to be used as the starting point for resolution.
     * @param relativePath - The relative path to be resolved against the base URL.
     * @param mediaPath - The media path to be resolved against the previously resolved URL.
     * @returns The fully constructed URL as a string.
     */
    private getFinalUrlforSegments(baseURL: string, relativePath: string, mediaPath: string): string {
        const resolvedUrl = helperUtils.constructFullUrl(relativePath, baseURL).toString(); 
        return helperUtils.constructFullUrl(mediaPath, resolvedUrl).toString();
    }

    /**
     * Formats the media data by constructing complete URLs for video segments and updating segment information.
     *
     * @param mediaData - An array of media data objects to be formatted. Each object should contain information
     * such as `segments`, `init_segment`, and `index_segment`.
     * @param basePath - The base path used to construct the complete URL.
     * @param baseUrl - The base URL used to construct the complete URL and index segment URL.
     * @returns An array of formatted media data objects with updated segment URLs, base64-encoded initialization
     * segments, and index segment URLs.
     */
    private formatSegmentsData(mediaData: AudioFormatMetadata[] | VideoFormatMetadata[], basePath: string, baseUrl: string, videoUrl: string): VideoFormat[] | AudioFormat[] {
        return mediaData.map((data) => {
            const completeUrl = helperUtils.constructFullUrl(basePath, videoUrl).toString();
            const videoSegments: string[] = data.metaData.segments.map(segment =>
                this.getFinalUrlforSegments(completeUrl, data.base_url, segment.url)
            );
            const mediaDataObject = data.audioFormatData ? data.audioFormatData : data.videoFormatData;
    
            return {
                ...mediaDataObject,
                segments: videoSegments,
                indexSegmentUrl: baseUrl + data.metaData.index_segment
            };
        });
    }    

    /**
     * Filters the provided media data based on supported formats for the Vimeo video provider.
     *
     * @param mediaData - An array of media data objects to be filtered.
     * @returns A promise that resolves to an array of filtered media data objects.
     * 
     * @throws Will throw an error if fetching the supported formats fails.
     */
    private async getFilteredAudioData(audioData: any[]): Promise<AudioFormatMetadata[]> {
        const supportedFormats: SupportedFormat = await cdnConfigManager.getSupportedFormats(VIDEO_PROVIDER.VIMEO);
        const filteredData: AudioFormatMetadata[] = vimeoMediaFormatFilter.getFilteredAudioData(audioData, supportedFormats.audio);
        return filteredData;
    }

    /**
     * Filters the provided video data to include only the supported video formats for Vimeo.
     *
     * @param videoData - An array of video metadata objects to be filtered.
     * @returns A promise that resolves to an array of filtered video format metadata objects.
     *
     * @throws Will throw an error if fetching supported formats fails.
     */
    private async getFilteredVideoData(videoData: any[]): Promise<VideoFormatMetadata[]> {
        const supportedFormats: SupportedFormat = await cdnConfigManager.getSupportedFormats(VIDEO_PROVIDER.VIMEO);
        const filteredData: VideoFormatMetadata[] = vimeoMediaFormatFilter.getFilteredVideoData(videoData, supportedFormats.video);
        return filteredData;
    }

    /**
     * Retrieves metadata information for a given video ID.
     * @param videoId - The ID of the video to fetch metadata for.
     * @returns A promise that resolves to the metadata of the video.
     */
    async getMetadataInfo(videoId: string): Promise<VideoMetaData> {
        try {
            let metaDataUrl = await cdnConfigManager.getMetadataUrl(VIDEO_PROVIDER.VIMEO);
            if (!metaDataUrl) {
                throw new Error('Unable to get the metadata url');
            }
            metaDataUrl = metaDataUrl.replace('${videoId}', videoId);
            const response: Response = await fetch(metaDataUrl);
            const html: string = await response.text();
            if (!response.ok) {
                throw new Error(`Metadata fetch failed - ${metaDataUrl}`);
            }
            const playerConfigRegex = await cdnConfigManager.getVideoProviderMetaData(VIDEO_PROVIDER.VIMEO, VIDEO_PROVIDER_PROPERTY_MAP.playerConfigRegex);
            const match: string[] = html.match(playerConfigRegex);
            // If regex pattern contains paranthesis 0th index will be the entire string that matched and the next subsequent indexes will be values captured by each set of parentheses in the regex
            if (!match || !match[1]) {
                throw new Error(`No player config available for ${videoId}`);
            }
            const playerConfig = JSON.parse(match[1]);
            const videoFiles = playerConfig.request?.files;
            if (!videoFiles) {
                throw new Error('Video Files are not available in the requested playerconfig path');
            }

            const supportedStreamingProtocol: METADATA_STREAMING_PROTOCOLS = await this.filterSupportedStreamingProtocol(Object.keys(playerConfig.request.files) as unknown as METADATA_STREAMING_PROTOCOLS[]);
            const cdns = videoFiles[supportedStreamingProtocol].cdns;
            const defaultCdn = videoFiles[supportedStreamingProtocol].default_cdn;
            if (!cdns || !defaultCdn || !cdns[defaultCdn]) {
                throw new Error(`Supported video source data not available for ${videoId}`);
            }
        
            const supportedVideoDataUrl: string = await this.getSupportedVideoDataUrl(cdns[defaultCdn]);
            if (!supportedVideoDataUrl) {
                throw new Error(`No supported url exists for ${videoId}`);
            }

            const videoDataResponse: Response = await fetch(supportedVideoDataUrl);
            if (!videoDataResponse.ok) {
                throw new Error(`Failed to fetch video data - ${supportedVideoDataUrl}`);
            }

            const videoData = await videoDataResponse.json();
            if (!videoData.audio) {
                console.log('No audio data available');
                return null;
            }

            let filteredAudioData: AudioFormatMetadata[] = await this.getFilteredAudioData([...videoData.audio]);
            if (!filteredAudioData || filteredAudioData.length === 0) {
                console.log("inside if")
                console.log('No supported audio data');
                return null;
            }

            let filteredVideoData: VideoFormatMetadata[] = await this.getFilteredVideoData([...videoData.video]);
            const baseUrl: string = helperUtils.constructFullUrl(videoData.base_url, supportedVideoDataUrl).toString();
            const formattedAudioData: AudioFormat[] = this.formatSegmentsData(filteredAudioData, videoData.base_url, baseUrl, supportedVideoDataUrl) as AudioFormat[];
            const formattedVideoData: VideoFormat[] = this.formatSegmentsData(filteredVideoData, videoData.base_url, baseUrl, supportedVideoDataUrl) as VideoFormat[];
            return {
                formats: {
                    audioFormats: [...formattedAudioData],
                    videoFormats: [...formattedVideoData]
                },
                videoDetails: {
                    title: playerConfig.video.title,
                    videoId: String(playerConfig.video.id),
                    thumbnail: playerConfig.video.thumbnail_url
                }
            };
        } catch(error) {
            console.error(`Error in getting metadata for ${videoId} - ${error}`);
            
            // Handle 403 errors specifically
            if (error.status === 403) {
                console.error('403 error detected in Vimeo extractor, setting last fetched timestamp to prevent immediate retry');
                await MetadataValidityUtils.setLastFetchedTimestamps(videoId, VIDEO_PROVIDER.VIMEO);
            }
            
            return null;
        }
    }
}

const vimeoMetaDataExtractor = new VimeoMetaDataExtractor();
export default vimeoMetaDataExtractor;