import { BYTE_TO_GB_CONVERSION, BYTE_TO_MB_CONVERSION, BYTE_TO_KB_CONVERSION, HD_TEXT, MEDIA_SIZE, KBPS_CONVERSION_VALUE, VIDEO_PROVIDER } from "./constants";
import {  AudioFormatMetadata, VideoFormatMetadata } from "./interfaces";
import { MediaFormatFilter } from "./MediaFormatFilter";
import cdnConfigManager from "./background/CDNConfigManager";

class YoutubeMediaFormatFilter extends MediaFormatFilter {
    
    private static readonly DEFAULT_MAX_SUPPORTED_CONTENT_LENGTH = 1610612736; // 1.5 * 1024 * 1024 * 1024 = 1610612736  (1.5GB)
    
    private maxSupportedContentLength: number = YoutubeMediaFormatFilter.DEFAULT_MAX_SUPPORTED_CONTENT_LENGTH;
    
    constructor() {
        super();
        this.initialize();
    }
    
    /**
     * Initializes the maxSupportedContentLength from CDN config
     */
    private async initialize(): Promise<void> {
        this.maxSupportedContentLength = await cdnConfigManager.getMaxSupportedContentLength(VIDEO_PROVIDER.YOUTUBE, YoutubeMediaFormatFilter.DEFAULT_MAX_SUPPORTED_CONTENT_LENGTH);
    }
    
    private formatCommonAttributes(data: any) {
        const contentLength: number = Math.floor((data.bitrate * ( data.approxDurationMs / 1000 )) / 8);
        // Calculate content length in MB or GB as a number, depending on size
        const { value: contentLengthInKbOrMbOrGb, resolutionUnit: contentLengthUnit } = this.getContentLengthInClosestUnits(contentLength);

        return {
            approxDurationMs: data.approxDurationMs,
            averageBitrate: data.averageBitrate,
            bitrate: Math.floor(data.bitrate / 1000),
            mimeType: data.mimeType,
            url: data.url,
            codecs: data.codecs,
            container: data.container,
            contentLengthInKbOrMbOrGb: contentLengthInKbOrMbOrGb,
            contentLengthUnit: contentLengthUnit,
            calculatedContentLength: contentLength,
            initSegmentBase64: null, // YouTube doesn't use init segments
            metaData: {
                base_url: null,
                index_segment: null, // YouTube doesn't use index segments
                segments: data.segments || [] // Use segments from getBasicDecipheredInfoInSegments
            }
        }
    }
    /**
     * Formats an array of audio data objects into an array of `AudioFormat` objects.
     *
     * @param dataArray - An array of audio data objects to be formatted.
     * Each object in the array should contain properties such as `duration`, `bitrate`, `channels`, `sample_rate`, `avg_bitrate`, `mime_type`, `url`, and `codecs`.
     *
     * @returns An array of `AudioFormat` objects, where each object includes:
     * - `approxDurationMs`: The approximate duration of the audio in milliseconds.
     * - `audioChannels`: The number of audio channels.
     * - `audioSampleRate`: The audio sample rate as a string.
     * - `averageBitrate`: The average bitrate of the audio.
     * - `bitrate`: The bitrate of the audio.
     * - `contentLength`: The content length of the audio in bytes.
     * - `mimeType`: The MIME type of the audio.
     * - `url`: The URL of the audio resource.
     * - `audioBitrate`: The bitrate of the audio.
     * - `audioCodec`: The codec used for the audio.
     * - `codecs`: The codec used for the audio (duplicate of `audioCodec`).
     * - `container`: The container format extracted from the MIME type.
     * - `contentLengthInMb`: The content length of the audio in megabytes.
     *
     * Note:
     * - The `duration` is converted from seconds to milliseconds.
     * - The `contentLength` is calculated based on the bitrate and duration.
     * - The `container` is extracted by splitting the MIME type using a predefined pattern.
     */
    formatAudioData(dataArray: any[]): AudioFormatMetadata[] {
        const uniqueMap = new Map<number, AudioFormatMetadata>();
        for (const data of dataArray) {
            const currentBitrate = data.audioBitrate;
            const currentContentLength = data.contentLength;
            const contentLengthInfo = this.getContentLengthInClosestUnits(currentContentLength);
            
            // Skip processing if contentLengthInfo.value is null or undefined
            if (contentLengthInfo?.value == null) {
                continue;
            }
            
            const contentLengthKey = contentLengthInfo.value;
            const existingAudioFormatData = uniqueMap.get(contentLengthKey);
            
            // If no existing format for this content length, or current bitrate is higher, use current format
            if (!existingAudioFormatData || (currentBitrate > existingAudioFormatData.audioFormatData.audioBitrate * KBPS_CONVERSION_VALUE)) {
                const commonAttributes = this.formatCommonAttributes(data);
                
                // Filter out content lengths that exceed maxSupportedContentLength
                if (commonAttributes.calculatedContentLength > this.maxSupportedContentLength) {
                    console.debug('Skipping audio format: calculatedContentLength ${commonAttributes.calculatedContentLength} exceeds maxSupportedContentLength ${this.maxSupportedContentLength}');
                    continue;
                }
                
                const audioFormatData = {
                    ...commonAttributes,
                    audioChannels: data.audioChannels,
                    audioSampleRate: data.audioSampleRate,
                    audioBitrate: (data.audioBitrate) / KBPS_CONVERSION_VALUE,
                    audioCodec: data.audioCodec,
                    segments: commonAttributes.metaData.segments || []
                };
                audioFormatData.contentLengthInKbOrMbOrGb = commonAttributes.contentLengthInKbOrMbOrGb;
                const metaData = { ...commonAttributes.metaData };
                uniqueMap.set(contentLengthKey, { audioFormatData, metaData });
            }
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Transforms an array of video data objects into an array of `VideoFormat` objects.
     *
     * @param dataArray - An array of video data objects containing information such as duration, bitrate, mime type, etc.
     * @returns An array of `VideoFormat` objects with calculated and formatted properties.
     *
     * The transformation includes:
     * - Converting the duration from seconds to milliseconds (`approxDurationMs`).
     * - Calculating the content length in bytes and converting it to megabytes (`contentLengthInMb`).
     * - Extracting and formatting properties such as `mimeType`, `container`, `qualityLabel`, and `height`.
     */
    formatVideoData(dataArray: any[]): VideoFormatMetadata[] {
        const uniqueMap = new Map<string, VideoFormatMetadata>();
        for (const data of dataArray) {
            const currentQualityLabelKey = data.qualityLabel;
            const currentContentLength = data.contentLength;
            const existingVideoFormatData = uniqueMap.get(currentQualityLabelKey);
            // Optimized content length comparison using helper method
            const existingContentLength = existingVideoFormatData?.videoFormatData?.contentLengthUnit 
            ? this.convertToBytes(
                existingVideoFormatData.videoFormatData.contentLengthInKbOrMbOrGb,
                existingVideoFormatData.videoFormatData.contentLengthUnit
              )
            : 0;
            if (!existingVideoFormatData || (currentContentLength > existingContentLength)) {
                const commonAttributes = this.formatCommonAttributes(data);
                
                // Filter out content lengths that exceed maxSupportedContentLength
                if (commonAttributes.calculatedContentLength > this.maxSupportedContentLength) {
                    console.debug('Skipping video format: calculatedContentLength ${commonAttributes.calculatedContentLength} exceeds maxSupportedContentLength ${this.maxSupportedContentLength}');
                    continue;
                }
                
                const videoFormatData = {
                    ...commonAttributes,
                    qualityLabel: data.qualityLabel,
                    height: data.height,
                    isHDFormat: data.quality.includes(HD_TEXT.toLowerCase()),
                    segments: commonAttributes.metaData.segments || []
                };
                videoFormatData.contentLengthInKbOrMbOrGb = commonAttributes.contentLengthInKbOrMbOrGb;
                const metaData = { ...commonAttributes.metaData };
                uniqueMap.set(currentQualityLabelKey, { videoFormatData, metaData });
            }
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Filters the provided data based on the specified supported formats.
     * @param data - The data object to be filtered, containing properties such as `mime_type` and `codecs`.
     * @param supportedFormats - An array of supported formats, where each format specifies a `mimeType` and a list of `codecs`.
     * @returns A boolean indicating whether the data matches any of the supported formats.
     */
    filterData(data: any, supportedFormats: any): any[] {
        return supportedFormats.some(rule => {
            const mimeMatch = !rule.mimeType || data.mimeType.includes(rule.mimeType);
            const codecMatch = rule.codecs.some(codec =>
              data.mimeType.includes(codec)
            );
            return mimeMatch && codecMatch;
        });
    }
}
const youtubeMediaFormatFilter = new YoutubeMediaFormatFilter();
export { youtubeMediaFormatFilter };