    import Innertube, { UniversalCache, Utils, Types } from '@avast/youtube-downloader-lib';
    import { VideoMetaData, MediaMetaDataExtractor, AudioFormat, AudioFormatMetadata, MEDIA_TYPE, VideoFormatMetadata, VideoFormat, SupportedFormat, FAILURE_REASONS, SpecialTelemetryType, MEDIA_CONTAINER_FORMAT} from './interfaces';
    import { VIDEO_PROVIDER, YOUTUBE_CONSTANTS, VIDEO_DOWNLOAD_METRICS_KEY, METADATA_403_LAST_ERROR_TIMESTAMP, MESSAGE_TYPES} from './constants';
    import { youtubeMediaFormatFilter } from './YoutubeMediaFormatFilter';
    import cdnConfigManager from './background/CDNConfigManager';
    import { telemetryManager } from './telemetry/telemetryManager';
    import { MetadataValidityUtils } from './utils/MetadataValidityUtils';
    import helperUtils from './utils/HelperUtils';
    import { StorageUtils } from './utils/storageUtils';
    import sandboxExecutor from './sandbox/SandboxExecutor';
    class YoutubeMetaDataExtractor implements MediaMetaDataExtractor  {

        // determines whether live videos are present in this provider
        isLiveVideoApplicable = true;
        
        // Innertube instance 
        private innerTube: Innertube;
        
        // Options for YouTube API calls
        private youtubeOptions: Types.GetVideoChunkInfoOptions;
        
        // Instance variables for chunk configuration
        private chunkSizeInBytes: number;
        private chunkSizeInCount: number;
        private maxSupportedContentLength: number;
        private maxSegmentableContentLength: number;
        private maxSupportedVideoDurationInMs: number;
        private botDetectionConfig: {botConditions: Array<{status: string, reason: string}>} | null = null;
        
        // PoToken and visitor data for YouTube authentication
        private visitorData: string;
        private poToken: string;
        
        // Promise that resolves when initialization is complete
        private initializationPromise: Promise<void>;
        
        private static DEFAULT_MAX_CHUNK_SIZE_MB = 10485760; // 10 * 1024 * 1024 = 10485760  (10MB)
        private static DEFAULT_MAX_CHUNKS = 154;
        private static DEFAULT_MAX_SUPPORTED_CONTENT_LENGTH = 1610612736; // 1.5 * 1024 * 1024 * 1024 = 1610612736  (1.5GB)
        private static DEFAULT_MAX_SEGMENTABLE_CONTENT_LENGTH = 1610612736; // 1.5 * 1024 * 1024 * 1024 = 1610612736  (1.5GB)
        private static DEFAULT_MAX_SUPPORTED_VIDEO_DURATION_MS = 7200000; // 2 * 60 * 60 * 1000 = 7200000  (2 hours)
        

        constructor() {
            // Don't auto-initialize - wait for explicit init() call
            // This allows VideoDownloaderBG to create offscreen document first
            this.initializationPromise = Promise.resolve();
        }
        
        /**
         * Initialize the extractor. Must be called after offscreen document is ready.
         * Called by VideoDownloaderBG.init() after offscreen document is created.
         */
        async init(): Promise<void> {
            this.initializationPromise = this.initializeInnerTube();
            await this.initializationPromise;
        }

        /**
         * Initializes the Innertube instance and loads configuration values
         */
        private async initializeInnerTube(): Promise<void> {
            // Initialize sandbox executor to configure Platform.shim.eval
            sandboxExecutor.initialize();
            // Get player ID from CDN config, if available
            const playerId = await cdnConfigManager.getPlayerId(VIDEO_PROVIDER.YOUTUBE);
            
            // Request PoTokens and WAIT for them before creating Innertube
            await this.initializePoTokensFromOffscreen();
            
            // Create Innertube instance WITH tokens
            const innertubeOptions: any = { 
                cache: new UniversalCache(false),
                generate_session_locally: true
            };
            if (playerId) {
                innertubeOptions.player_id = playerId;
            }
            
            // Add tokens to options - they should be set now
            if (this.visitorData && this.poToken) {
                innertubeOptions.po_token = this.poToken;
                innertubeOptions.visitor_data = this.visitorData;
                console.log('Innertube creating with tokens:', {
                    visitorData: this.visitorData.substring(0, 20) + '...',
                    poToken: this.poToken.substring(0, 20) + '...'
                });
            } else {
                console.warn('Creating Innertube WITHOUT tokens - visitorData or poToken not set');
            }
            
            this.innerTube = await Innertube.create(innertubeOptions);
            
            // Load chunk configuration from CDN config with fallback to defaults
            this.chunkSizeInBytes = await cdnConfigManager.getChunkSizeInBytes(VIDEO_PROVIDER.YOUTUBE, YoutubeMetaDataExtractor.DEFAULT_MAX_CHUNK_SIZE_MB);
            this.chunkSizeInCount = await cdnConfigManager.getChunkSizeInCount(VIDEO_PROVIDER.YOUTUBE, YoutubeMetaDataExtractor.DEFAULT_MAX_CHUNKS);
            this.maxSupportedContentLength = await cdnConfigManager.getMaxSupportedContentLength(VIDEO_PROVIDER.YOUTUBE, YoutubeMetaDataExtractor.DEFAULT_MAX_SUPPORTED_CONTENT_LENGTH);
            this.maxSegmentableContentLength = await cdnConfigManager.getMaxSegmentableContentLength(VIDEO_PROVIDER.YOUTUBE, YoutubeMetaDataExtractor.DEFAULT_MAX_SEGMENTABLE_CONTENT_LENGTH);
            this.maxSupportedVideoDurationInMs = await cdnConfigManager.getMaxSupportedVideoDurationInMs(VIDEO_PROVIDER.YOUTUBE, YoutubeMetaDataExtractor.DEFAULT_MAX_SUPPORTED_VIDEO_DURATION_MS);
            this.botDetectionConfig = await cdnConfigManager.getBotDetectionConfig(VIDEO_PROVIDER.YOUTUBE);
            
            // Load client configuration from CDN config with fallback to default constant
            const clientIdentifier = await cdnConfigManager.getClient(VIDEO_PROVIDER.YOUTUBE, YOUTUBE_CONSTANTS.CLIENT);
            
            // Initialize YouTube options with CDN-configured or default client
            this.youtubeOptions = {
                client: clientIdentifier as Types.InnerTubeClient,
                chunkSizeInBytes: this.chunkSizeInBytes,
                chunkSizeInCount: this.chunkSizeInCount,
                maxSupportedContentLength: this.maxSupportedContentLength,
                maxSegmentableContentLength: this.maxSegmentableContentLength,
            };
        }

        /**
         * Requests PoTokens from the offscreen document.
         * 
         * Note: The offscreen document is initialized by VideoDownloaderBG.init() 
         * before any listeners are set up, so it's guaranteed to be ready.
         * 
         * The offscreen document handles all token generation logic:
         * 1. PRIMARY: Tries sandbox-based generation (secure but may fail PMD:Undefined)
         * 2. FALLBACK: Uses content script bridge to access YouTube's existing VM
         * 3. Returns placeholder token if all else fails
         */
        private async initializePoTokensFromOffscreen(): Promise<void> {
            try {
                const response = await new Promise<any>((resolve, reject) => {
                    chrome.runtime.sendMessage(
                        { type: MESSAGE_TYPES.GENERATE_PO_TOKENS },
                        (response) => {
                            if (chrome.runtime.lastError) {
                                reject(new Error(chrome.runtime.lastError.message));
                            } else {
                                resolve(response);
                            }
                        }
                    );
                });

                if (response?.payload?.success && response?.payload?.tokens) {
                    const { visitorData, poToken } = response.payload.tokens;
                    this.visitorData = visitorData;
                    this.poToken = poToken;
                    
                    console.log('PoTokens received successfully:', {
                        tokenLength: this.poToken?.length
                    });
                } else {
                    console.error('Failed to get PoTokens from offscreen:', response?.payload?.error);
                }
            } catch (error: any) {
                console.error('Error requesting PoTokens from offscreen:', error);
            }
        }

        /**
         * Filters the provided audio data based on supported audio formats for YouTube.
         *
         * @param audioData - An array of audio data objects to be filtered.
         * @returns A promise that resolves to an array of filtered audio format metadata.
         *
         * @throws Will throw an error if fetching supported formats fails or if filtering encounters issues.
         */
        private async getFilteredAudioData(audioData: any[]): Promise<AudioFormatMetadata[]> {
            const supportedFormats: SupportedFormat = await cdnConfigManager.getSupportedFormats(VIDEO_PROVIDER.YOUTUBE);
            const filteredData: AudioFormatMetadata[] = youtubeMediaFormatFilter.getFilteredAudioData(audioData, supportedFormats.audio);
            return filteredData;
        }

        /**
         * Filters the provided video data to include only the supported video formats for Vimeo.
         *
         * @param videoData - An array of video metadata objects to be filtered.
         * @returns A promise that resolves to an array of filtered video format metadata objects.
         *
         * @throws Will throw an error if fetching supported formats fails.
         */
        private async getFilteredVideoData(videoData: any[]): Promise<VideoFormatMetadata[]> {
            const supportedFormats: SupportedFormat = await cdnConfigManager.getSupportedFormats(VIDEO_PROVIDER.YOUTUBE);
            const filteredData: VideoFormatMetadata[] = youtubeMediaFormatFilter.getFilteredVideoData(videoData, supportedFormats.video);
            return filteredData;
        }

        /**
         * Retrieves metadata information for a given video ID.
         * @param videoId - The ID of the video to fetch metadata for.
         * @returns A promise that resolves to the metadata of the video.
         */
        async getMetadataInfo(videoId: string): Promise<VideoMetaData> {
            try {
                // Wait for initialization to complete before making any requests
                await this.initializationPromise;
                
                // Include po_token in options for each request
                const optionsWithToken = {
                    ...this.youtubeOptions,
                    po_token: this.poToken
                };
                
                const videoInfo = await this.innerTube.getBasicDecipheredInfoInSegments(videoId, optionsWithToken);
                
                // Check for bot detection first - can come with 200 status
                const videoDetails = this.extractVideoDetailsFromVideoInfo(videoInfo);
                const isBotDetected = this.botDetectionConfig?.botConditions.some(condition => 
                    videoDetails?.playabilityStatus?.status === condition.status && 
                    videoDetails?.playabilityStatus?.reason === condition.reason
                );
                if (isBotDetected) {
                    console.error('Bot detection detected in Youtube extractor, setting last fetched timestamp to prevent immediate retry');
                    telemetryManager.sendSpecialTelemetry(SpecialTelemetryType.metadataTelemetry);
                    await MetadataValidityUtils.incrementAuthErrorCounts(videoId, VIDEO_PROVIDER.YOUTUBE);
                    return null;
                }
                
                const formats = await this.extractFormatsFromVideoInfo(videoInfo);
                if ( !formats || formats.length === 0 || formats[0]?.approxDurationMs > this.maxSupportedVideoDurationInMs) {
                    return null;
                }
                if (videoDetails && !videoDetails.isLiveContent) {
                    // Increment the count of videos played in storage for heartbeat telemetry
                    await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.VIDEOS_PLAYED_COUNT);
                    const audioData = formats.filter(format => format.mimeType.includes(MEDIA_TYPE.AUDIO));
                    const videoData = formats.filter(format => format.mimeType.includes(MEDIA_TYPE.VIDEO));
                    const filteredAudioFormatsMetadata: AudioFormatMetadata[] = await this.getFilteredAudioData(audioData);
                    const filteredVideoFormatsMetadata: VideoFormatMetadata[] = await this.getFilteredVideoData(videoData);
                    if (filteredAudioFormatsMetadata.length === 0 || filteredVideoFormatsMetadata.length === 0) {
                        return null;
                    }
                    const thumbnailData = videoDetails.thumbnails ? videoDetails.thumbnails: {};
                    const filteredAudioData: AudioFormat[] = filteredAudioFormatsMetadata.map(data => data.audioFormatData);
                    const filteredVideoData: VideoFormat[] = filteredVideoFormatsMetadata.map(data => data.videoFormatData);
                    return {
                        formats: {
                            audioFormats: [...filteredAudioData],
                            videoFormats: [...filteredVideoData]
                        },
                        videoDetails: {
                            title: videoDetails.title,
                            videoId: videoDetails.videoId,
                            thumbnail: thumbnailData ? thumbnailData[0]?.url : ''
                        }
                    }
                }
            } catch (errorData) {
                console.error('Error in YoutubeMetaDataExtractor getMetadataInfo:', errorData);
                // Handle 403 errors specifically by setting last fetched timestamp
                if ( errorData.message?.includes('403') || errorData.status === 403 ) {
                    console.error('403 error detected in Youtube extractor, setting last fetched timestamp to prevent immediate retry');
                    telemetryManager.sendSpecialTelemetry(SpecialTelemetryType.metadataTelemetry);
                    await MetadataValidityUtils.incrementAuthErrorCounts(videoId, VIDEO_PROVIDER.YOUTUBE);
                } else if (errorData?.videoDetails?.isLiveContent === false) {
                    // Increment the count of videos played in storage for heartbeat telemetry
                    await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.VIDEOS_PLAYED_COUNT);
                    // Increment the count of non supported videos in storage for heartbeat telemetry
                    await StorageUtils.incrementMetricsCount(VIDEO_DOWNLOAD_METRICS_KEY.NOT_SUPPORTED_VIDEOS_COUNT);
                }
                
                return null
            }
        }

        /**
         * Extracts formats from YouTube.js VideoInfo response and maps them to the expected format structure
         * @param videoInfo - YouTube.js VideoInfo object
         * @returns Array of format objects compatible with existing interfaces
         */
        private async extractFormatsFromVideoInfo(videoInfo: any): Promise<any[]> {
            const formats: any[] = [];
            
            // Extract from streaming_data.formats
            if (videoInfo.streaming_data?.formats) {
                for (const format of videoInfo.streaming_data.formats) {
                    formats.push(await this.updateFormatPropertyNames(format));
                }
            }
            
            // Extract from streaming_data.adaptive_formats
            if (videoInfo.streaming_data?.adaptive_formats) {
                for (const format of videoInfo.streaming_data.adaptive_formats) {
                    formats.push(await this.updateFormatPropertyNames(format));
                }
            }
            
            return formats;
        }

        /**
         * Extracts container format from mimeType using the same approach as ytdl
         * @param mimeType - MIME type string (e.g., "video/mp4", "audio/webm")
         * @returns Container format string (e.g., "mp4", "webm")
         */
        private async extractContainerFromMimeType(mimeType: string): Promise<string> {
            if (!mimeType) {
                // Get default mime type from CDN config
                const defaultMimeType = await cdnConfigManager.getDefaultMimeType(VIDEO_PROVIDER.YOUTUBE, MEDIA_CONTAINER_FORMAT.MP4);
                return defaultMimeType;
            }
            
            const container = mimeType.split(";")[0].split("/")[1];
            if (!container) {
                // Get default mime type from CDN config if extraction fails
                const defaultMimeType = await cdnConfigManager.getDefaultMimeType(VIDEO_PROVIDER.YOUTUBE, MEDIA_CONTAINER_FORMAT.MP4);
                return defaultMimeType;
            }
            return container;
        }

        /**
         * Updates only the property names that differ between YouTube.js and expected format structure
         * @param ytFormat - YouTube.js format object
         * @returns Updated format object with corrected property names
         */
        private async updateFormatPropertyNames(ytFormat: any): Promise<any> {
            const updatedFormat = { ...ytFormat };
            
            // Only update properties that have different names or need special handling
            if (ytFormat.mime_type) {
                updatedFormat.mimeType = ytFormat.mime_type;
            }
            
            if (ytFormat.quality_label) {
                updatedFormat.qualityLabel = ytFormat.quality_label;
            }
            
            if (ytFormat.audio_channels) {
                updatedFormat.audioChannels = ytFormat.audio_channels;
            }
            
            if (ytFormat.audio_sample_rate) {
                updatedFormat.audioSampleRate = ytFormat.audio_sample_rate;
            }
            
            if (ytFormat.bitrate) {
                updatedFormat.audioBitrate = ytFormat.bitrate;
            }
            
            if (ytFormat.audio_codec) {
                updatedFormat.audioCodec = ytFormat.audio_codec;
            }
            
            if (ytFormat.approx_duration_ms) {
                updatedFormat.approxDurationMs = ytFormat.approx_duration_ms;
            }
            
            if (ytFormat.average_bitrate) {
                updatedFormat.averageBitrate = ytFormat.average_bitrate;
            }
            
            if (ytFormat.content_length) {
                updatedFormat.contentLength = ytFormat.content_length;
            }
            
            if (ytFormat.has_audio !== undefined) {
                updatedFormat.hasAudio = ytFormat.has_audio;
            }
            
            if (ytFormat.has_video !== undefined) {
                updatedFormat.hasVideo = ytFormat.has_video;
            }
            
            updatedFormat.container = ytFormat.container || await this.extractContainerFromMimeType(ytFormat.mime_type);
            
            return updatedFormat;
        }

        /**
         * Extracts video details from YouTube.js VideoInfo response
         * @param videoInfo - YouTube.js VideoInfo object
         * @returns Video details object compatible with existing interfaces
         */
        private extractVideoDetailsFromVideoInfo(videoInfo: any): any {
            const basicInfo = videoInfo.basic_info;
            
            return {
                title: basicInfo?.title || '',
                videoId: basicInfo?.id || '',
                thumbnails: basicInfo?.thumbnail || {},
                isLiveContent: basicInfo?.is_live || false,
                lengthSeconds: basicInfo?.duration?.seconds || 0,
                playabilityStatus: videoInfo.playability_status || null,
            };
        }

        /**
         * Loads a new tab and fetch the media info 
         * @param videoId - The ID of the video to fetch metadata from youtube api.
         * @returns A promise that resolves to the metadata of the video.
         */
        async postMediaInfo(url: string, videoId: string): Promise<VideoMetaData> {
            return null;
        }
    }

    const youtubeMetaDataExtractor = new YoutubeMetaDataExtractor();
    export default youtubeMetaDataExtractor;
