import { BYTE_TO_GB_CONVERSION, BYTE_TO_MB_CONVERSION, BYTE_TO_KB_CONVERSION, MIMETYPE_SPLIT_PATTERN, MEDIA_SIZE, KBPS_CONVERSION_VALUE, HD_RESOLUTION } from "./constants";
import { AudioFormatMetadata, VideoFormatMetadata } from "./interfaces";
import { MediaFormatFilter } from "./MediaFormatFilter";

class VimeoMediaFormatFilter extends MediaFormatFilter {
    
    private formatCommonAttributes(data: any) {
        const duration: string = Number((data.duration * 1000).toFixed(0)).toString(); // sec -> ms
        const contentLength: number = Math.floor((data.bitrate * data.duration) / 8);
        const { value: contentLengthInKbOrMbOrGb, resolutionUnit: contentLengthUnit } = this.getContentLengthInClosestUnits(contentLength);

        return {
            approxDurationMs: duration,
            averageBitrate: data.avg_bitrate,
            bitrate: Math.floor(data.bitrate / 1000),
            mimeType: data.mime_type,
            url: data.url,
            codecs: data.codecs,
            container: data.mime_type.split(MIMETYPE_SPLIT_PATTERN)[1],
            contentLengthInKbOrMbOrGb,
            contentLengthUnit,
            initSegmentBase64: data.init_segment,
            metaData: {
                base_url: data.base_url,
                index_segment: data.index_segment,
                segments: data.segments
            }
        };
    }
    /**
     * Formats an array of audio data objects into an array of `AudioFormat` objects.
     *
     * @param dataArray - An array of audio data objects to be formatted.
     * Each object in the array should contain properties such as `duration`, `bitrate`, `channels`, `sample_rate`, `avg_bitrate`, `mime_type`, `url`, and `codecs`.
     *
     * @returns An array of `AudioFormat` objects, where each object includes:
     * - `approxDurationMs`: The approximate duration of the audio in milliseconds.
     * - `audioChannels`: The number of audio channels.
     * - `audioSampleRate`: The audio sample rate as a string.
     * - `averageBitrate`: The average bitrate of the audio.
     * - `bitrate`: The bitrate of the audio.
     * - `contentLength`: The content length of the audio in bytes.
     * - `mimeType`: The MIME type of the audio.
     * - `url`: The URL of the audio resource.
     * - `audioBitrate`: The bitrate of the audio.
     * - `audioCodec`: The codec used for the audio.
     * - `codecs`: The codec used for the audio (duplicate of `audioCodec`).
     * - `container`: The container format extracted from the MIME type.
     * - `contentLengthInMb`: The content length of the audio in megabytes.
     *
     * Note:
     * - The `duration` is converted from seconds to milliseconds.
     * - The `contentLength` is calculated based on the bitrate and duration.
     * - The `container` is extracted by splitting the MIME type using a predefined pattern.
     */
    formatAudioData(dataArray: any[]): AudioFormatMetadata[] {
        const uniqueMap = new Map<number, AudioFormatMetadata>();
        for (const data of dataArray) {
            const currentQualityLabelKey = data.bitrate;
            const currentContentLength = data.contentLength; // in bytes
            const existingAudioFormatData = uniqueMap.get(currentQualityLabelKey);
            // Optimized content length comparison using helper method
            const existingContentLength = existingAudioFormatData?.audioFormatData?.contentLengthUnit 
            ? this.convertToBytes(
                existingAudioFormatData.audioFormatData.contentLengthInKbOrMbOrGb,
                existingAudioFormatData.audioFormatData.contentLengthUnit
              )
            : 0;

            if (!existingAudioFormatData || (currentContentLength > existingContentLength)) {
                const commonAttibutes = this.formatCommonAttributes(data);
                const audioFormatData = {
                    ...commonAttibutes,
                    audioChannels: data.channels,
                    audioSampleRate: data.sample_rate.toString(),
                    audioBitrate: ( data.bitrate ) / KBPS_CONVERSION_VALUE,
                    audioCodec: data.codecs,
                };
                audioFormatData.contentLengthInKbOrMbOrGb = commonAttibutes.contentLengthInKbOrMbOrGb;
                const metaData = { ...commonAttibutes.metaData };
                uniqueMap.set(currentQualityLabelKey, { audioFormatData, metaData });
            }
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Transforms an array of video data objects into an array of `VideoFormat` objects.
     *
     * @param dataArray - An array of video data objects containing information such as duration, bitrate, mime type, etc.
     * @returns An array of `VideoFormat` objects with calculated and formatted properties.
     *
     * The transformation includes:
     * - Converting the duration from seconds to milliseconds (`approxDurationMs`).
     * - Calculating the content length in bytes and converting it to megabytes (`contentLengthInMb`).
     * - Extracting and formatting properties such as `mimeType`, `container`, `qualityLabel`, and `height`.
     */
    formatVideoData(dataArray: any[]): VideoFormatMetadata[] {
        const uniqueMap = new Map<number, VideoFormatMetadata>();
        for (const data of dataArray) {
            const currentQualityLabelKey = data.height;
            const currentContentLength = data.contentLength; // in bytes
            const existingVideoFormatData = uniqueMap.get(currentQualityLabelKey);
            // Optimized content length comparison using helper method
            const existingContentLength = existingVideoFormatData?.videoFormatData?.contentLengthUnit 
            ? this.convertToBytes(
                existingVideoFormatData.videoFormatData.contentLengthInKbOrMbOrGb,
                existingVideoFormatData.videoFormatData.contentLengthUnit
              )
            : 0;

            if (!existingVideoFormatData || (currentContentLength > existingContentLength)) {
                const commonAttibutes = this.formatCommonAttributes(data);
                const videoFormatData = {
                    ...commonAttibutes,
                    qualityLabel: `${data.height}p`,
                    height: data.height,
                    isHDFormat: data.height >= HD_RESOLUTION
                };
                videoFormatData.contentLengthInKbOrMbOrGb = commonAttibutes.contentLengthInKbOrMbOrGb;
                const metaData = { ...commonAttibutes.metaData };
                uniqueMap.set(currentQualityLabelKey, { videoFormatData, metaData });
            }
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Filters the provided data based on the specified supported formats.
     * @param data - The data object to be filtered, containing properties such as `mime_type` and `codecs`.
     * @param supportedFormats - An array of supported formats, where each format specifies a `mimeType` and a list of `codecs`.
     * @returns A boolean indicating whether the data matches any of the supported formats.
     */
    filterData(data: any, supportedFormats: any): any[] {
        return supportedFormats.some(rule => {
            const mimeMatch = !rule.mimeType || rule.mimeType === data.mime_type;
            const codecMatch = rule.codecs.some(codec =>
              data.codecs.toLowerCase().startsWith(codec.toLowerCase())
            );
            return mimeMatch && codecMatch;
        });
    }
}
const vimeoMediaFormatFilter = new VimeoMediaFormatFilter();
export { vimeoMediaFormatFilter };