  /**
   * @function sendDownloadClickEvent
   * @desc Sends telemetry event when download button is clicked.
   * @param origin - Whether it's from POPUP or IN_VIDEO
   */
  async sendDownloadClickEvent(origin: TELEMETRY_ORIGIN): Promise<void> {
    await this.init();

    const downloadClickEvent: any = {
      event: TelemetryEventNames.extnClick,
      action: TELEMETRY_ACTION.DOWNLOAD
    };

    if (origin === TELEMETRY_ORIGIN.POPUP) {
      downloadClickEvent.collection = TELEMETRY_COLLECTION.MAIN_MENU;
      downloadClickEvent.screen_id = TELEMETRY_SCREEN_ID.MAIN_MENU;
      downloadClickEvent.label = TELEMETRY_LABEL.TOOLBAR;
    } else {
      downloadClickEvent.collection = TELEMETRY_COLLECTION.IN_VIDEO_DOWNLOAD;
      downloadClickEvent.screen_id = TELEMETRY_SCREEN_ID.IN_VIDEO_DOWNLOAD;
    }

    this.trackingServerAnalyticsFacade.sendEvent(downloadClickEvent);
  }

